window.SITE_DATA = Object.assign(window.SITE_DATA || {}, {"eventViewerCodes":[{"id":"41","source":"Kernel-Power","level":"critical","urgency":"repeat-check","summary":"Windows가 정상 종료 절차를 거치지 못한 뒤 다시 시작되었음을 기록합니다. 파워서플라이 고장을 단독으로 확정하는 이벤트는 아닙니다.","conditions":["전원 차단 또는 강제 종료 뒤","게임·렌더링 중 갑작스러운 재부팅","절전 복귀 실패 뒤"],"causes":["사용자 강제 종료","과열 또는 전원 불안정","드라이버·메모리 오류로 인한 멈춤"],"checks":["발생 직전 작업과 온도 기록","같은 시각의 WHEA·BugCheck 이벤트 확인","24핀·EPS·GPU 전원과 메모리 기본 설정 점검"],"warnings":["반복되고 저장 중 전원이 꺼진다면 먼저 중요한 파일을 백업하세요.","이벤트 41만으로 PSU를 교체하지 마세요."],"relatedCodes":["0x00000124","0x0000009F"],"relatedGuides":["hardware-gaming-reboot.html","hardware-overheat-shutdown.html"],"detailPage":"event-kernel-power-41.html"},{"id":"6008","source":"EventLog","level":"error","urgency":"repeat-check","summary":"이전 시스템 종료가 예상하지 못한 방식으로 끝났음을 나타내는 사후 기록입니다.","conditions":["정전·강제 종료 뒤","블루스크린 뒤 자동 재부팅","시스템 멈춤 뒤 전원 버튼 사용"],"causes":["비정상 종료 결과","전원 공급 중단","커널 또는 드라이버 멈춤"],"checks":["같은 시각 직전의 오류 확인","신뢰성 모니터에서 중단 원인 비교","Kernel-Power 41과 BugCheck 1001 동반 여부 확인"],"warnings":["원인이 아니라 종료 결과를 기록한 경우가 많습니다."],"relatedCodes":["0x00000124"],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-eventlog-6008.html"},{"id":"1074","source":"User32","sourceAliases":["USER32","Microsoft-Windows-User32"],"level":"information","urgency":"info","summary":"사용자나 특정 프로세스가 Windows 종료·재시작을 요청했을 때 남는 계획된 종료 기록입니다. 갑작스러운 전원 차단인지는 이 이벤트의 요청 주체와 이유를 함께 봐야 합니다.","conditions":["Windows Update 뒤 자동 재시작","시작 메뉴·shutdown 명령으로 종료","관리 도구나 설치 프로그램이 재부팅 요청"],"causes":["사용자 직접 종료","Windows Update 또는 설치 프로그램","WMI·관리 도구가 보낸 종료 요청"],"checks":["Description의 프로세스·사용자·Reason Code 기록","같은 시각의 Windows Update·설치 이벤트 비교","1074 뒤 실제 재부팅이 이어졌는지 6008·41과 시간 비교"],"warnings":["1074는 계획된 종료 요청 기록입니다. 이 이벤트만으로 원치 않는 종료나 악성 동작을 확정하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-user32-1074.html"},{"id":"1002","source":"Application Hang","sourceAliases":["Application Hang","Microsoft-Windows-Application-Experience"],"level":"error","urgency":"driver","summary":"응용 프로그램이 일정 시간 응답하지 않아 Windows가 멈춤 상태로 기록한 이벤트입니다. 앱 충돌 1000과 달리 프로세스가 종료되지 않고 기다리는 상황이 핵심입니다.","conditions":["창에 응답 없음 표시","게임·탐색기·문서 앱이 멈춤","잠시 후 회복되거나 강제 종료"],"causes":["앱 내부 작업 또는 플러그인 대기","그래픽·저장장치·네트워크 응답 지연","오버레이·보안 프로그램 충돌"],"checks":["응답하지 않은 앱 이름과 Hang 유형 기록","같은 앱에서만 재현되는지 비교","오버레이·플러그인을 끄고 클린 부팅에서 재현","동시각 Disk·Display·Application Error 이벤트 확인"],"warnings":["1002만으로 RAM이나 저장장치 고장을 확정하지 마세요. 멈춘 앱과 작업 조건이 더 중요한 단서입니다."],"relatedCodes":["0xC0000005"],"relatedGuides":["windows-explorer-freeze.html","windows-app-not-launching.html"],"detailPage":"event-application-hang-1002.html"},{"id":"1","source":"Power-Troubleshooter","sourceAliases":["Power Troubleshooter","Microsoft-Windows-Power-Troubleshooter"],"level":"information","urgency":"info","summary":"절전 또는 대기 상태에서 Windows가 깨어난 원인을 기록합니다. 예약 작업·전원 버튼·USB 장치·네트워크 어댑터가 원인일 수 있습니다.","conditions":["절전 중 PC가 저절로 깨어남","밤새 켜져 있거나 팬이 다시 동작","절전 복귀 시각을 확인해야 함"],"causes":["전원 버튼·키보드·마우스 입력","예약 작업 또는 Windows Update","USB·네트워크 장치의 절전 해제 허용"],"checks":["Wake Source와 Wake Source Type 기록","powercfg /lastwake 결과와 비교","장치 관리자 전원 관리의 절전 해제 허용 확인","예약 작업의 절전 해제 옵션과 업데이트 시간을 비교"],"warnings":["정보 수준 기록이며 고장 이벤트가 아닙니다. 원치 않는 절전 해제가 반복될 때만 설정을 좁혀 확인하세요."],"relatedCodes":[],"relatedGuides":["windows-sleep-resume-fail.html"],"detailPage":"event-power-sleep-wake.html"},{"id":"42","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"Windows가 절전 또는 대기 상태로 진입했음을 기록합니다. 절전 진입 직전 드라이버 오류나 복귀 실패가 있었는지는 주변 이벤트와 함께 확인해야 합니다.","conditions":["절전 버튼을 눌렀을 때","덮개를 닫거나 유휴 시간이 지난 뒤","절전·최대 절전 전환 시"],"causes":["사용자 또는 전원 계획에 따른 정상 절전","업데이트·유휴 시간 정책","절전 진입을 유발한 전원 관리 설정"],"checks":["SleepTime·WakeTime과 실제 사용 시각 비교","절전 전후 Driver Power State 9F 여부 확인","복귀 실패 시 Power-Troubleshooter 1과 WHEA·Display 이벤트 비교"],"warnings":["42 자체는 오류가 아닙니다. 절전 복귀 실패가 있을 때만 9F·드라이버·BIOS 설정을 함께 점검하세요."],"relatedCodes":["0x0000009F"],"relatedGuides":["windows-sleep-resume-fail.html"],"detailPage":"event-power-sleep-wake.html"},{"id":"1026","source":".NET Runtime","sourceAliases":["Microsoft-Windows-.NET Runtime",".NET Runtime"],"level":"error","urgency":"driver","summary":".NET 프로그램에서 처리되지 않은 예외가 발생해 프로세스가 종료된 기록입니다. Application Error 1000의 오류 모듈·예외 코드와 함께 보면 앱 문제와 공용 런타임 문제를 구분하기 쉽습니다.","conditions":[".NET 앱 실행 직후 종료","특정 기능에서 예외 창 표시","이벤트 1000과 같은 시각에 반복"],"causes":["앱 코드 또는 설정 오류","필요한 .NET 런타임 구성 요소 누락","플러그인·권한·파일 접근 문제"],"checks":["Exception 문장과 앱 이름 기록","Application Error 1000의 오류 모듈·예외 코드 비교","앱 복구 후 필요한 .NET 구성 요소와 업데이트 확인","여러 .NET 앱에서 반복되면 시스템 파일과 저장장치 상태 확인"],"warnings":["1026만으로 .NET을 무조건 삭제·재설치하지 마세요. 예외 유형과 해당 앱의 요구 버전을 먼저 확인하세요."],"relatedCodes":["0xC0000005","0x80070005"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-dotnet-runtime-1026.html"},{"id":"1000","source":"Application Error","level":"error","urgency":"driver","summary":"응용 프로그램이 예외를 처리하지 못하고 종료되었을 때 충돌 모듈과 예외 코드를 남깁니다.","conditions":["앱 실행 직후 종료","특정 기능 사용 중 반복 충돌"],"causes":["손상된 앱 파일","플러그인·오버레이 충돌","그래픽 또는 런타임 구성 요소 문제"],"checks":["오류 응용 프로그램 이름과 오류 모듈 기록","앱 업데이트·복구","클린 부팅에서 재현 여부 확인"],"warnings":["시스템 전체 고장으로 단정하지 마세요."],"relatedCodes":["0xC0000005","0x80070005"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-application-error-1000.html"},{"id":"1001","source":"Windows Error Reporting","sourceAliases":["BugCheck","Windows Error Reporting","WER-SystemErrorReporting"],"level":"error","urgency":"repeat-check","summary":"BugCheck 또는 Windows Error Reporting 원본으로 기록되는 1001 이벤트입니다. 블루스크린, 앱 충돌 또는 장치 오류가 Windows 오류 보고에 등록됐음을 나타냅니다.","conditions":["블루스크린 자동 재부팅 뒤","앱 충돌 보고 생성 뒤"],"causes":["BugCheck 발생","응용 프로그램 장애","하드웨어 오류 보고"],"checks":["BugcheckCode와 매개 변수 확인","덤프 파일 생성 여부 확인","같은 시각의 Kernel-Power·WHEA 확인"],"warnings":["보고 유형을 확인하기 전에는 블루스크린으로 단정하지 마세요."],"relatedCodes":["0x000000EF","0x00000124"],"relatedGuides":["windows-bsod-critical-process.html"],"detailPage":"event-wer-1001.html"},{"id":"20","source":"WindowsUpdateClient","sourceAliases":["Microsoft-Windows-WindowsUpdateClient"],"level":"error","urgency":"repeat-check","summary":"Windows Update Agent가 특정 업데이트 설치에 실패했음을 기록합니다. 이벤트 설명에 업데이트 이름과 오류 코드가 함께 남으므로 코드 자체를 별도로 확인해야 합니다.","conditions":["누적 업데이트 설치 실패","드라이버 업데이트 반복 실패","Windows 11 업그레이드 중 중단"],"causes":["업데이트 구성 요소나 다운로드 캐시 손상","디스크 여유 공간·시스템 예약 파티션 부족","특정 장치 드라이버와 업데이트의 호환성 문제","VPN·프록시·보안 프로그램이 업데이트 연결을 방해하는 경우"],"checks":["이벤트 설명의 updateTitle과 errorCode 기록","설정의 Windows Update 기록과 같은 KB 실패 여부 비교","여유 공간과 날짜·시간·네트워크 확인","같은 KB가 반복되면 Microsoft Update 카탈로그나 제조사 드라이버 안내를 기준으로 대체 경로 확인"],"warnings":["이벤트 20만으로 업데이트 전체가 고장 났다고 판단하지 마세요. 실패한 KB와 오류 코드를 함께 봐야 합니다.","BIOS·레지스트리 변경보다 실패한 업데이트와 장치 드라이버를 먼저 분리하세요."],"relatedCodes":["0x800F0922","0x80070002","0x80070005"],"relatedGuides":["windows-update-fail-loop.html","windows-11-upgrade-blocked.html"],"detailPage":"event-windowsupdateclient-20.html"},{"id":"7","source":"Disk","level":"error","urgency":"backup","summary":"저장장치에서 읽을 수 없는 블록이 감지되었음을 알리는 기록입니다.","conditions":["파일 복사 지연","부팅 중 디스크 접근","특정 파일을 열 때 멈춤"],"causes":["배드 섹터 또는 NAND 오류","케이블·슬롯 접촉 문제","컨트롤러 문제"],"checks":["중요 파일 즉시 백업","SMART·제조사 진단 확인","케이블·포트 교차 점검"],"warnings":["검사나 복구 명령보다 데이터 백업을 먼저 진행하세요."],"relatedCodes":["0x0000007A","0x00000077"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-disk-7.html"},{"id":"51","source":"Disk","level":"warning","urgency":"backup","summary":"페이징 작업 중 저장장치 입출력 오류가 발생했음을 나타냅니다.","conditions":["대용량 작업 중 멈춤","페이지 파일 접근 중 지연"],"causes":["디스크 응답 지연","케이블·전원 불안정","저장장치 상태 저하"],"checks":["백업 후 SMART 확인","SATA 케이블·M.2 장착 상태 점검","이벤트 7·129·153 동반 여부 확인"],"warnings":["반복될수록 데이터 손실 위험이 커질 수 있습니다."],"relatedCodes":["0x0000007A"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-disk-51.html"},{"id":"55","source":"Ntfs","level":"error","urgency":"backup","summary":"NTFS 파일 시스템 구조에서 손상이 감지되었음을 나타냅니다.","conditions":["부팅 후 디스크 검사 안내","파일·폴더 접근 오류"],"causes":["비정상 종료","저장장치 오류","파일 시스템 메타데이터 손상"],"checks":["중요 데이터 백업","디스크 건강 상태 확인","백업 후 chkdsk 검사 계획"],"warnings":["고장 징후가 있으면 쓰기 작업이 많은 복구를 먼저 실행하지 마세요."],"relatedCodes":["0x00000024","0x000000ED"],"relatedGuides":["windows-auto-repair-loop.html"],"detailPage":"event-ntfs-55.html"},{"id":"129","source":"storahci","sourceAliases":["storport","stornvme","Microsoft-Windows-StorPort"],"level":"warning","urgency":"backup","summary":"저장장치 요청이 시간 안에 끝나지 않아 컨트롤러가 장치를 재설정한 기록입니다. 원본이 storahci·storport·stornvme 중 무엇인지에 따라 SATA·NVMe·스토리지 컨트롤러 범위를 좁힐 수 있습니다.","conditions":["몇 초간 시스템 멈춤","NVMe·SATA 응답 지연","부팅이 간헐적으로 느림"],"causes":["SSD 펌웨어·컨트롤러 문제","전원 관리 호환성","케이블·슬롯 또는 장치 상태","저장장치 부하가 컨트롤러 처리량을 넘은 경우"],"checks":["이벤트의 원본과 RaidPort 번호 기록","동일 시각 이벤트 153·7·11과 WHEA 17을 비교","SSD 펌웨어와 건강 상태 확인","전원 관리·칩셋 드라이버·케이블·M.2 장착 상태 점검"],"warnings":["반복되면 먼저 백업하고 저장장치 교차 테스트를 준비하세요.","이벤트 129 하나만으로 SSD 고장을 확정하지 말고 건강 상태·WHEA·부하 조건을 함께 보세요."],"relatedCodes":["0x00000133","0x0000007A"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-storahci-129.html"},{"id":"153","source":"Disk","level":"warning","urgency":"backup","summary":"디스크 입출력 작업이 재시도되었음을 나타내며 일시적 지연 또는 연결 문제의 단서가 됩니다.","conditions":["복사 중 속도 급락","게임 로딩 중 멈춤"],"causes":["장치 응답 지연","케이블·포트 문제","필터 드라이버 영향"],"checks":["발생 디스크 번호 확인","이벤트 129·7 동반 여부 확인","백업 후 연결과 SMART 점검"],"warnings":["반복되면 단순 성능 문제로 넘기지 마세요."],"relatedCodes":["0x0000007A"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-disk-153.html"},{"id":"98","source":"Disk","level":"error","urgency":"backup","summary":"볼륨을 오프라인으로 전환해 전체 CHKDSK를 실행해야 한다는 기록입니다. 파일 시스템 손상이나 저장장치 I/O 문제가 함께 있는지 확인해야 합니다.","conditions":["Windows가 디스크 검사를 예약함","파일 시스템 오류·볼륨 접근 지연","Disk·Ntfs 오류가 같은 시각에 반복"],"causes":["비정상 종료나 쓰기 실패로 인한 파일 시스템 손상","저장장치 불량 섹터·I/O 완료 실패","스토리지 컨트롤러·케이블·필터 드라이버 문제"],"checks":["검사 전에 중요한 데이터를 다른 저장장치에 백업","이벤트에 표시된 볼륨과 디스크를 특정","fsutil dirty query 드라이브:로 dirty 상태 확인","백업 후 필요할 때 chkdsk /f 또는 제조사 지침에 따른 검사를 실행","Disk 7·11·51·129·153과 Ntfs 55·140을 같은 시각으로 비교"],"warnings":["불안정한 디스크에 검사·복구 명령을 먼저 실행하면 추가 쓰기 부담이 생길 수 있습니다. 백업이 우선입니다.","일반 여유 공간 부족과 파일 시스템 손상은 다른 문제이므로 저장 공간 확보만으로 해결된다고 보지 마세요."],"relatedCodes":["0x00000024","0x0000007A"],"relatedGuides":["hardware-nvme-delay.html","windows-auto-repair-loop.html"],"detailPage":"event-disk-98.html"},{"id":"158","source":"Disk","level":"warning","urgency":"repeat-check","summary":"두 개 이상의 디스크가 동일한 식별자나 GUID를 사용하고 있음을 나타냅니다. 복제한 VHD, 다중 경로 저장장치, USB 외장 디스크 환경에서 주로 확인합니다.","conditions":["디스크를 추가·복제한 뒤","외장 디스크나 VHD가 여러 개 연결됨","디스크 번호·볼륨 식별이 예상과 다름"],"causes":["복사한 VHD가 같은 디스크 식별자를 유지","MPIO 없이 동일 물리 디스크에 여러 경로가 노출","저장장치·가상 디스크 복제 과정의 식별자 중복"],"checks":["Get-Disk에서 Number·FriendlyName·UniqueId를 확인","동일 장치의 다중 경로라면 MPIO·스토리지 구성을 점검","복제 VHD라면 원본과 사본을 구분한 뒤 Set-VHD -Path 경로 -ResetDiskIdentifier를 검토","USB 외장 디스크는 안전 제거 후 하나씩 연결해 어떤 장치에서 발생하는지 확인","중복 식별자를 임의로 바꾸기 전에 백업과 대상 디스크를 확실히 확인"],"warnings":["158은 그 자체로 디스크 고장이나 성능 저하를 의미하지 않을 수 있습니다. 동일 식별자 경고와 실제 I/O 장애를 구분하세요.","diskpart나 디스크 초기화 명령으로 식별자를 바꾸면 데이터가 손실될 수 있으므로 대상 확인 없이 실행하지 마세요."],"relatedCodes":[],"relatedGuides":["hardware-nvme-delay.html","event-viewer-guide.html"],"detailPage":"event-disk-158.html"},{"id":"140","source":"Ntfs","level":"warning","urgency":"backup","summary":"NTFS가 트랜잭션 로그에 데이터를 flush하지 못했으며 볼륨 손상이 발생할 수 있다고 기록한 이벤트입니다. 저장장치 I/O 경로와 파일 시스템 상태를 함께 확인해야 합니다.","conditions":["저장 중 멈춤 또는 지연","외장 디스크·가상 머신 스냅샷 작업 중","Ntfs 55·50 또는 Disk 오류 동반"],"causes":["저장장치 응답 지연·연결 끊김","SATA·USB·스토리지 컨트롤러 문제","전원 차단이나 비정상 종료","필터 드라이버·가상화 저장장치 문제"],"checks":["중요 파일을 먼저 백업하고 이벤트의 VolumeId·DeviceName 기록","Disk 7·11·51·98·129·153과 같은 시각인지 비교","SMART·케이블·포트·M.2 장착 상태 확인","백업 후 fsutil dirty query와 제조사 진단 도구로 볼륨·장치 상태 점검","반복되면 저장장치·컨트롤러·필터 드라이버 업데이트와 교차 테스트"],"warnings":["140만으로 파일이 이미 손상됐다고 단정하지는 않지만, 반복되면 데이터 손실 위험을 고려해 쓰기 작업을 줄이고 백업을 우선하세요."],"relatedCodes":["0x00000024"],"relatedGuides":["hardware-nvme-delay.html","windows-auto-repair-loop.html"],"detailPage":"event-ntfs-140.html"},{"id":"1","source":"WHEA-Logger","level":"error","urgency":"repeat-check","summary":"WHEA가 수정할 수 없는 하드웨어 오류를 오류 레코드로 기록한 항목입니다. 이벤트 18과 달리 표시되는 오류 원본·유형을 직접 확인해야 CPU, PCIe, 메모리 계층을 구분할 수 있습니다.","conditions":["블루스크린 또는 강제 재부팅 전후","게임·렌더링 같은 고부하 작업","화면 멈춤 없이 이벤트만 반복"],"causes":["CPU 코어·캐시 또는 메모리 컨트롤러 불안정","PCIe 장치·링크 오류","XMP·EXPO·오버클럭·언더볼팅 설정","BIOS·칩셋·장치 펌웨어 문제","CPU·RAM·GPU·메인보드·전원 계층의 물리적 불안정"],"checks":["Details의 ErrorSource, ErrorType, Processor APIC ID, PCIe 장치 정보를 기록","XMP·EXPO와 오버클럭을 끄고 기본 설정에서 재현 여부 비교","BIOS·칩셋·GPU·SSD 펌웨어를 제조사 자료 기준으로 확인","같은 시각의 Kernel-Power 41, BugCheck 1001, WHEA 17·18·19를 함께 비교","반복되면 중요한 파일을 백업한 뒤 CPU·RAM·GPU·PCIe 장치를 한 번에 하나씩 교차 테스트"],"warnings":["WHEA 1만으로 특정 부품을 확정하지 마세요. 오류 레코드의 원본과 반복 조건이 더 중요합니다.","백업 없이 장시간 스트레스 테스트를 반복하지 마세요."],"relatedCodes":["0x00000124","0x0000009C"],"relatedGuides":["hardware-gaming-reboot.html","hardware-overheat-shutdown.html"],"detailPage":"event-viewer-guide.html"},{"id":"17","source":"WHEA-Logger","level":"warning","urgency":"repeat-check","summary":"PCIe 계열 하드웨어 오류가 수정되어 시스템이 계속 실행된 기록입니다.","conditions":["GPU·NVMe 부하 중","절전 복귀 뒤"],"causes":["PCIe 링크 불안정","장치 펌웨어·드라이버","오버클럭 또는 전원 관리"],"checks":["장치 ID와 버스 위치 확인","BIOS·칩셋·장치 펌웨어 확인","기본 클럭에서 반복 여부 점검"],"warnings":["수정된 오류라도 반복 횟수가 늘면 점검이 필요합니다."],"relatedCodes":["0x00000124"],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-whea-logger-17.html"},{"id":"18","source":"WHEA-Logger","level":"error","urgency":"backup","summary":"CPU, 메모리 또는 인터커넥트에서 수정할 수 없는 하드웨어 오류가 보고된 기록입니다.","conditions":["부하 중 재부팅","유휴 상태에서 갑작스러운 멈춤","오버클럭 적용 상태"],"causes":["CPU 코어·캐시 불안정","메모리·Infinity Fabric 불안정","전원·온도 또는 BIOS 설정"],"checks":["중요 데이터 백업","XMP·EXPO·오버클럭 해제","오류 유형과 APIC ID를 기록해 부품별 교차 테스트","위 점검으로도 반복되면 CPU 자체 결함 가능성을 열어두고 교체(또는 타 시스템 테스트)를 고려"],"warnings":["반복되면 장시간 부하 테스트보다 백업과 기본 설정 복원이 우선입니다.","오버클럭 해제·설정 복원 후에도 반복되다가 CPU를 교체한 뒤에야 해결된 사례가 있어, 반복 빈도가 높다면 CPU 불량 가능성을 낮게 보지 마세요."],"relatedCodes":["0x00000124","0x0000009C"],"relatedGuides":["hardware-gaming-reboot.html","hardware-overheat-shutdown.html"],"detailPage":"event-whea-logger-18.html"},{"id":"19","source":"WHEA-Logger","level":"warning","urgency":"repeat-check","summary":"수정된 하드웨어 오류가 보고된 기록으로 CPU·메모리·PCIe 상태를 함께 봐야 합니다.","conditions":["부하 전환 중","절전 복귀 뒤"],"causes":["일시적 전압·클럭 불안정","BIOS 설정","장치 링크 오류"],"checks":["오류 구성 요소 확인","기본 BIOS 설정에서 재현 여부 확인","반복 횟수와 작업 조건 기록"],"warnings":["단발성보다 반복 패턴이 중요합니다."],"relatedCodes":["0x00000124"],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-whea-logger-19.html"},{"id":"20","source":"WHEA-Logger","level":"error","urgency":"backup","summary":"치명적 하드웨어 오류가 보고되었으며 오류 레코드의 구성 요소 확인이 필요합니다.","conditions":["블루스크린 또는 재부팅 직전"],"causes":["CPU·메모리·PCIe 장치 오류","전원·열 불안정"],"checks":["백업","오류 레코드와 같은 시각 이벤트 확인","기본 설정에서 부품별 테스트"],"warnings":["반복되면 사용을 줄이고 원인 부품을 분리 점검하세요."],"relatedCodes":["0x00000124"],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-whea-logger-20.html"},{"id":"46","source":"WHEA-Logger","level":"error","urgency":"backup","summary":"메모리 계층을 포함한 치명적 하드웨어 오류 기록으로 나타날 수 있습니다.","conditions":["메모리 부하 중","부팅·절전 복귀 중"],"causes":["RAM·메모리 컨트롤러 불안정","XMP·EXPO 설정","보드·CPU 접촉 문제"],"checks":["중요 데이터 백업","메모리 기본 속도 복원","모듈과 슬롯 교차 테스트"],"warnings":["오류가 반복되면 메모리 검사 결과만으로 정상 판정하지 마세요."],"relatedCodes":["0x0000001A","0x00000124"],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-whea-logger-46.html"},{"id":"47","source":"WHEA-Logger","level":"warning","urgency":"repeat-check","summary":"수정된 하드웨어 오류가 발생했으며, 오류 구성 요소가 메모리로 표시되는 경우 RAM·메모리 컨트롤러·메모리 설정을 우선 확인해야 합니다.","conditions":["부하 중 또는 유휴 상태에서 반복","예기치 않은 재부팅 전후","이벤트 XML의 Component가 Memory로 표시"],"causes":["RAM 모듈 불안정 또는 접촉 불량","XMP·EXPO·메모리 오버클럭 설정","CPU 메모리 컨트롤러·BIOS 호환성","메인보드 슬롯 또는 전원 안정성 문제"],"checks":["오류 횟수·Component·ErrorSource·PhysicalAddress를 XML에서 기록","XMP·EXPO와 오버클럭을 끄고 기본 메모리 속도에서 재현 여부 확인","RAM 모듈을 한 개씩 같은 슬롯에서 검사한 뒤 슬롯을 바꿔 교차 테스트","MemTest86+ 또는 Windows 메모리 진단을 실행하고 WHEA 19·46·Kernel-Power 41과 발생 시각 비교","반복되면 중요 파일을 백업하고 BIOS·칩셋 업데이트와 메모리 호환 목록을 확인"],"warnings":["수정된 오류라는 이유만으로 무시하지 마세요. 짧은 시간에 반복되거나 재부팅·블루스크린이 동반되면 하드웨어 불안정 신호일 수 있습니다.","WHEA 47만으로 특정 RAM 모듈이나 CPU를 확정하지 말고 모듈·슬롯·기본 설정을 나눠 검사하세요."],"relatedCodes":["0x0000001A","0x00000124"],"relatedGuides":["hardware-gaming-reboot.html","memory-test-guide.html"],"detailPage":"event-whea-logger-47.html"},{"id":"4101","source":"Display","level":"warning","urgency":"driver","summary":"그래픽 드라이버가 응답하지 않아 Windows가 드라이버를 복구한 기록입니다.","conditions":["화면 깜빡임","게임 중 검은 화면","브라우저·영상 재생 중 멈춤"],"causes":["그래픽 드라이버 충돌","GPU 과열·전원 불안정","오버클럭·하드웨어 가속 문제"],"checks":["드라이버 버전과 발생 앱 기록","GPU 온도·보조전원 확인","안정 버전 드라이버에서 재현 비교"],"warnings":["화면 깨짐이나 타는 냄새가 있으면 부하 테스트를 중단하세요."],"relatedCodes":["0x00000116","0x000000EA"],"relatedGuides":["hardware-no-display.html"],"detailPage":"event-display-4101.html"},{"id":"153","source":"nvlddmkm","sourceAliases":["NVIDIA Windows Kernel Mode Driver","NVIDIA Display Driver"],"level":"error","urgency":"driver","summary":"NVIDIA 그래픽 커널 드라이버가 GPU 응답을 복구하는 과정에서 남길 수 있는 이벤트입니다. 같은 ID라도 Disk 153과 의미가 다르므로 원본이 nvlddmkm인지 먼저 확인해야 합니다.","conditions":["게임 중 화면 멈춤·검은 화면","화면이 잠시 꺼졌다가 돌아옴","게임 종료 뒤 바탕화면으로 복귀","같은 시각 LiveKernelEvent 141·117 또는 Display 4101 동반"],"causes":["NVIDIA 드라이버 설치·업데이트 충돌","GPU 온도·전원·보조전원 케이블 불안정","GPU 오버클럭·언더볼팅 또는 불안정한 PCIe 링크","게임 오버레이·하드웨어 가속·보안 프로그램 충돌","GPU·VRAM 자체 이상"],"checks":["이벤트 XML의 Device\\Video 번호와 TDR 문구, 발생 앱·드라이버 버전을 기록","최근 드라이버 업데이트 직후라면 안전 모드에서 기존 NVIDIA 드라이버를 제거한 뒤 안정 버전을 새로 설치","GPU 온도·핫스팟·전력과 8핀/12V 보조전원 체결 상태를 확인하고 오버클럭·언더볼팅을 기본값으로 복원","오버레이와 하드웨어 가속을 끈 상태, 다른 게임 또는 기본 그래픽 설정에서 재현 여부 비교","반복되면 Display 4101, LiveKernelEvent 141·117, WHEA·Kernel-Power 이벤트의 같은 시각 기록을 함께 확인하고 중요한 파일을 백업"],"warnings":["nvlddmkm 153 하나만으로 그래픽카드 고장이나 파워서플라이 고장을 확정하지 마세요.","화면 깨짐·타는 냄새·커넥터 변색이 있으면 부하 테스트를 중단하고 전원을 분리한 뒤 점검하세요."],"relatedCodes":["0x00000116","0x00000117","0x00000119"],"relatedGuides":["hardware-no-display.html","hardware-gaming-reboot.html"],"detailPage":"event-nvlddmkm-153.html","copyKey":"nvlddmkm-153"},{"id":"141","source":"LiveKernelEvent","level":"error","urgency":"driver","summary":"신뢰성 기록에서 그래픽 드라이버 또는 GPU가 멈춘 뒤 Windows가 복구를 시도했을 때 자주 보이는 하드웨어 오류 보고입니다. 블루스크린 없이 게임 화면이 멈추거나 검은 화면이 된 뒤 복구되는 경우와 함께 확인합니다.","conditions":["게임·영상 렌더링 중 화면 멈춤 또는 검은 화면","드라이버가 복구된 뒤 게임만 종료","신뢰성 기록에 LiveKernelEvent 141 표시"],"causes":["GPU 드라이버 TDR(시간 초과 복구) 실패","GPU 온도·전원·오버클럭 불안정","그래픽카드·VRAM 또는 PCIe 연결 문제"],"checks":["신뢰성 기록의 Bucket ID와 같은 시각 Display 4101·WHEA 이벤트를 함께 확인","그래픽 드라이버를 안정 버전으로 재설치하고 GPU·VRAM 오버클럭 해제","GPU 온도·보조전원·케이블·PCIe 장착 상태를 확인"],"warnings":["코드 141만으로 그래픽카드 고장을 확정하지 마세요. 드라이버·온도·전원 조건을 기본값에서 비교하세요."],"relatedCodes":["0x00000116","0x00000117","0x00000119","0x00000113"],"relatedGuides":["hardware-no-display.html","hardware-gaming-reboot.html"],"detailPage":"event-display-4101.html"},{"id":"219","source":"Kernel-PnP","level":"warning","urgency":"driver","summary":"장치 드라이버가 시작 과정에서 로드되지 않았거나 지연되었음을 나타냅니다.","conditions":["부팅 직후","USB·블루투스 장치 연결 뒤"],"causes":["장치 드라이버 누락·충돌","빠른 시작 영향","분리된 장치의 잔여 서비스"],"checks":["장치 인스턴스와 드라이버 이름 확인","장치 관리자 상태 확인","제조사 드라이버 재설치"],"warnings":["문제 장치가 정상 작동하면 단발성 기록은 지켜볼 수 있습니다."],"relatedCodes":["0x0000009F"],"relatedGuides":["hardware-usb-not-detected.html"],"detailPage":"event-kernel-pnp-219.html"},{"id":"7000","source":"Service Control Manager","level":"error","urgency":"driver","summary":"Windows 서비스가 시작되지 못했음을 나타냅니다.","conditions":["부팅 직후","앱 또는 장치 서비스 시작 시"],"causes":["서비스 파일 누락","권한·계정 문제","제거된 프로그램 잔여 항목"],"checks":["서비스 이름과 오류 문구 확인","관련 앱·드라이버 상태 확인","필요 서비스인지 판단 후 복구"],"warnings":["서비스를 무작정 비활성화하지 마세요."],"relatedCodes":["0x80070422"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-service-7000.html"},{"id":"7001","source":"Service Control Manager","level":"error","urgency":"driver","summary":"의존하는 다른 서비스가 시작되지 않아 현재 서비스도 시작할 수 없음을 나타냅니다.","conditions":["부팅 또는 앱 시작 시"],"causes":["선행 서비스 실패","서비스 구성 손상"],"checks":["설명에 표시된 의존 서비스 확인","7000·7023 이벤트와 시간 비교","관련 앱 복구"],"warnings":["의존성 레지스트리를 임의 수정하지 마세요."],"relatedCodes":["0x80070422"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-service-7001.html"},{"id":"7009","source":"Service Control Manager","level":"error","urgency":"driver","summary":"서비스가 제한 시간 안에 연결되지 못했음을 나타냅니다.","conditions":["부팅 지연","앱 시작 지연"],"causes":["서비스 응답 지연","디스크·네트워크 병목","손상된 앱 구성"],"checks":["서비스 이름 확인","같은 시간 디스크·네트워크 이벤트 확인","앱 업데이트·복구"],"warnings":["시간 제한 값을 먼저 늘리기보다 지연 원인을 찾으세요."],"relatedCodes":[],"relatedGuides":["windows-startup-slow.html"],"detailPage":"event-service-7009.html"},{"id":"7011","source":"Service Control Manager","level":"error","urgency":"driver","summary":"서비스 제어 요청이 시간 안에 응답하지 않았음을 나타냅니다.","conditions":["종료·부팅 지연","장치 서비스 멈춤"],"causes":["서비스 교착","저장장치 지연","드라이버 응답 문제"],"checks":["서비스 이름 기록","디스크 129·153 동반 여부 확인","클린 부팅에서 재현 확인"],"warnings":["서비스 강제 삭제는 마지막 수단입니다."],"relatedCodes":["0x00000133"],"relatedGuides":["windows-startup-slow.html"],"detailPage":"event-service-7011.html"},{"id":"7023","source":"Service Control Manager","level":"error","urgency":"driver","summary":"서비스가 자체 오류 코드를 반환하며 종료된 기록입니다.","conditions":["기능 실행 실패","부팅 중 서비스 중단"],"causes":["서비스 구성·파일 손상","권한 또는 의존성 문제"],"checks":["이벤트 설명의 오류 코드 확인","관련 서비스 의존성 확인","앱 또는 Windows 구성 요소 복구"],"warnings":["오류 코드 없이 서비스만 재시작하면 재발 원인을 놓칠 수 있습니다."],"relatedCodes":["0x80070005"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-service-7023.html"},{"id":"7031","source":"Service Control Manager","level":"error","urgency":"driver","summary":"서비스가 예기치 않게 종료되었고 Windows가 재시작 같은 복구 작업을 예약한 기록입니다.","conditions":["앱·네트워크 기능이 갑자기 중단"],"causes":["서비스 충돌","관련 모듈·드라이버 오류"],"checks":["서비스 이름과 종료 횟수 확인","Application Error 1000 동반 여부 확인","관련 프로그램 복구"],"warnings":["반복 횟수가 증가할 때 조치하세요."],"relatedCodes":[],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-service-7031.html"},{"id":"7034","source":"Service Control Manager","level":"error","urgency":"driver","summary":"서비스가 예기치 않게 종료되었지만 자동 복구 동작 정보가 없는 기록입니다.","conditions":["특정 기능 갑작스러운 종료"],"causes":["서비스 자체 충돌","업데이트·구성 불일치"],"checks":["서비스 이름과 관련 앱 확인","최근 업데이트 비교","반복 여부 기록"],"warnings":["사용하지 않는 서비스인지 먼저 확인하세요."],"relatedCodes":[],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-service-7034.html"},{"id":"10016","source":"DistributedCOM","level":"warning","urgency":"info","summary":"특정 COM 구성 요소가 요청한 로컬 실행 또는 활성화 권한을 받지 못했다는 기록입니다. 정상 PC에서도 흔하며 대개 긴급하지 않습니다.","conditions":["부팅·로그인·앱 실행 중 단발성"],"causes":["Windows 기본 권한 설계","앱 구성 요소의 제한된 요청"],"checks":["실제 기능 장애가 함께 있는지 확인","같은 CLSID가 반복되는지 기록","문제가 없다면 관찰"],"warnings":["인터넷의 레지스트리·DCOM 권한 변경을 그대로 따라 하지 마세요."],"relatedCodes":["0x80070005"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-distributedcom-10016.html"},{"id":"10010","source":"DistributedCOM","level":"error","urgency":"driver","summary":"DCOM 서버가 제한 시간 안에 등록되지 않았음을 기록합니다. 특정 앱·서비스가 늦게 시작되거나 로그인·앱 실행이 지연될 때만 실제 증상과 연결해 봐야 합니다.","conditions":["로그인 직후 약 10~15초 지연","특정 앱·위젯·서비스 실행 지연","기능 장애 없이 부팅 때만 반복"],"causes":["연결된 서비스가 아직 시작되지 않은 경우","앱 구성 요소 또는 Windows 앱 패키지 지연","저장장치·CPU 사용률이 높은 상태","최근 앱 업데이트나 서비스 구성 충돌"],"checks":["이벤트의 CLSID·AppID와 서버 이름을 기록","같은 시각의 Service Control Manager 7000·7009·7011과 비교","실제로 지연되는 앱이나 기능이 있는지 확인","해당 앱 복구·업데이트와 클린 부팅에서 재현 여부를 비교"],"warnings":["10016처럼 단순히 권한을 바꾸는 해결책을 먼저 적용하지 마세요. 기능 장애가 없으면 관찰 대상일 수 있습니다."],"relatedCodes":["0x80070005"],"relatedGuides":["windows-startup-slow.html","windows-app-not-launching.html"],"detailPage":"event-viewer-guide.html"},{"id":"10005","source":"DistributedCOM","level":"error","urgency":"driver","summary":"DCOM이 필요한 서비스를 시작하려 했지만 오류를 반환했다는 기록입니다. 이벤트 설명에 서비스 이름과 오류 번호가 포함되므로 10005 자체보다 그 서비스를 먼저 확인해야 합니다.","conditions":["특정 기능 실행 실패","로그인·부팅 중 서비스 시작 오류","검색·인증·네트워크 기능이 함께 작동하지 않음"],"causes":["의존 서비스가 중지되었거나 시작 유형이 바뀐 경우","서비스 파일·앱 구성 손상","보안 정책이나 클린 부팅으로 서비스가 꺼진 경우"],"checks":["이벤트 설명의 서비스 이름과 오류 번호 기록","services.msc에서 해당 서비스와 의존 서비스 상태 확인","Service Control Manager 7000·7001·7023과 발생 시각 비교","필요 서비스라면 Windows 구성 요소 복구나 해당 앱 재설치를 검토"],"warnings":["모든 서비스를 일괄적으로 자동 시작으로 바꾸거나 레지스트리를 수정하지 마세요."],"relatedCodes":["0x80070422","0x80070005"],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-viewer-guide.html"},{"id":"162","source":"Volmgr","level":"error","urgency":"repeat-check","summary":"볼륨 관리자가 크래시 덤프 파일을 만드는 데 실패했다는 기록으로, 실제로는 예기치 않은 종료·재부팅과 함께 나타나는 경우가 많습니다.","conditions":["갑작스러운 재부팅이나 강제 종료 뒤","랜덤하게(며칠 간격으로) 전원이 꺼진 뒤"],"causes":["전원 공급(PSU) 불안정","메인보드 칩셋 드라이버가 오래된 경우","덤프 파일을 저장할 디스크 공간이나 페이지 파일 설정이 부족한 경우"],"checks":["같은 시각의 Kernel-Power(41)·WHEA 이벤트를 함께 확인하세요.","메인보드 제조사 홈페이지에서 칩셋 드라이버를 최신 버전으로 업데이트하세요.","설정 > 시스템 > 정보 > 고급 시스템 설정에서 가상 메모리(페이지 파일) 크기가 충분한지 확인하세요."],"warnings":["이 이벤트 자체가 원인을 확정하지는 않습니다 — 함께 나타난 다른 하드웨어 이벤트와 비교하세요."],"relatedCodes":["0x00000124"],"relatedGuides":["hardware-overheat-shutdown.html","hardware-no-power.html"],"detailPage":"event-volmgr-162.html"},{"id":"161","source":"Volmgr","level":"error","urgency":"repeat-check","summary":"블루스크린이나 시스템 중단 뒤 크래시 덤프를 저장하는 과정이 실패했음을 기록합니다. 이 이벤트는 원인이라기보다 장애 분석에 필요한 덤프가 남지 않은 이유를 보여주는 경우가 많습니다.","conditions":["블루스크린 뒤 미니덤프가 생성되지 않음","Kernel-Power 41 직전에 기록됨","덤프 파일 생성 실패 문구 표시"],"causes":["페이지 파일이 없거나 덤프 저장에 충분하지 않은 경우","덤프를 저장할 시스템 드라이브 공간 부족","저장장치 오류·부팅 디스크 접근 실패","예기치 않은 전원 차단으로 덤프 기록이 끝나지 않은 경우"],"checks":["C:\\Windows\\Minidump와 C:\\Windows\\MEMORY.DMP 생성 여부 확인","시스템 속성의 시작 및 복구에서 디버깅 정보 기록과 페이지 파일 설정 확인","시스템 드라이브 여유 공간과 Disk·Ntfs·storport 이벤트 비교","같은 시각의 BugCheck 1001·Kernel-Power 41·WHEA 기록 확인","덤프가 생성된 경우 미니덤프 분석기로 원인 드라이버를 별도 확인"],"warnings":["161만으로 GPU·PSU·저장장치 고장을 확정하지 마세요. 덤프 생성 실패와 실제 중단 원인을 분리해야 합니다.","저장장치 오류가 함께 있으면 덤프 설정을 바꾸기 전에 중요한 파일을 먼저 백업하세요."],"relatedCodes":["0x0000007A","0x0000009F"],"relatedGuides":["event-viewer-guide.html","hardware-gaming-reboot.html"],"detailPage":"event-viewer-guide.html"},{"id":"15","source":"TPM","level":"error","urgency":"driver","summary":"TPM(보안 칩) 장치 드라이버가 TPM 하드웨어에서 복구할 수 없는 오류를 감지했다는 기록으로, BitLocker나 Windows Hello 같은 TPM 기반 기능을 쓸 수 없게 됩니다.","conditions":["부팅 또는 로그인 중","BitLocker·Windows Hello 사용 시도 중"],"causes":["메인보드 BIOS/UEFI 펌웨어가 오래되어 TPM 모듈과 호환성 문제가 있는 경우","TPM 펌웨어 자체의 결함이나 초기화 실패","메인보드의 TPM 모듈(내장 또는 별도 헤더 장착형) 접촉 불량"],"checks":["메인보드 제조사 홈페이지에서 최신 BIOS/UEFI 펌웨어로 업데이트하세요.","tpm.msc를 실행해 TPM 상태를 확인하고, 필요하면 TPM 지우기(초기화)를 시도하세요.","별도 TPM 모듈을 장착하는 메인보드라면 모듈이 헤더에 완전히 꽂혀 있는지 확인하세요."],"warnings":["TPM 지우기(초기화)는 BitLocker로 암호화된 드라이브의 복구 키를 반드시 먼저 백업한 뒤 진행하세요."],"relatedCodes":[],"relatedGuides":["windows-11-upgrade-blocked.html"],"detailPage":"event-tpm-15.html"},{"id":"15","source":"HAL","level":"error","urgency":"driver","summary":"CPU의 IOMMU(입출력 메모리 관리 장치)가 특정 장치의 메모리 접근에서 오류를 감지했다는 하드웨어 수준 기록입니다. AMD-Vi·Intel VT-d를 사용하는 시스템에서 가상화·PCIe 장치와 관련해 나타날 수 있습니다.","conditions":["가상화(Hyper-V, WSL2 등)나 GPU 패스스루 사용 중","특정 PCIe 장치(GPU, NVMe, USB 컨트롤러 등) 연결 상태 변경 뒤","짧은 기간에 몰아서 반복되다가 이후 재발하지 않는 패턴"],"causes":["메인보드 BIOS·UEFI의 IOMMU(AMD-Vi·VT-d) 관련 설정이 최신이 아닌 경우","특정 PCIe 장치의 드라이버나 펌웨어가 DMA 접근을 잘못 요청하는 경우","가상화 소프트웨어(Hyper-V, VMware 등)와 하드웨어 IOMMU 매핑이 충돌하는 경우","메모리·PCIe 슬롯의 물리적 접촉 불량"],"checks":["메인보드 제조사 홈페이지에서 최신 BIOS 업데이트가 있는지 확인하세요.","이벤트의 장치(Device)와 FaultInformation 값을 기록해 같은 값이 반복되는지 확인하세요.","최근 추가·교체한 PCIe 장치(그래픽카드, NVMe, 확장카드)가 있다면 슬롯을 다시 장착해보세요.","Hyper-V·WSL2 등 가상화 기능을 쓰고 있다면 잠시 꺼보고 재현 여부를 비교하세요.","재부팅 뒤에도 반복되면 해당 장치를 다른 슬롯으로 옮기거나 제거해 원인 장치를 좁혀보세요."],"warnings":["이 이벤트 하나만으로 메인보드나 CPU 고장을 단정하지 마세요. 재발하지 않는다면 일시적인 드라이버·초기화 문제였을 가능성이 큽니다.","BIOS 업데이트 중 전원이 끊기면 메인보드가 손상될 수 있으니 노트북은 충전기를 연결한 채 진행하세요."],"relatedCodes":[],"relatedGuides":["windows-repair-tools-guide.html"],"detailPage":"event-hal-15.html"},{"id":"1801","source":"TPM-WMI","level":"error","urgency":"driver","summary":"업데이트된 Secure Boot 인증서가 있지만 아직 펌웨어에 적용되지 않았다는 기록입니다. 마이크로소프트가 진행 중인 Secure Boot 인증서 갱신(2011년 인증서 만료 대응) 롤아웃과 관련이 있습니다.","conditions":["Windows Update 후 시스템 로그에 반복 기록","부팅 시 눈에 띄는 증상 없이 조용히 쌓임","제조사 인증서를 사용하는 UEFI 펌웨어를 오래 업데이트하지 않은 경우"],"causes":["2026년 진행 중인 Windows Secure Boot 인증서 갱신 롤아웃의 대상인 경우","메인보드·노트북 제조사의 펌웨어 업데이트가 아직 적용되지 않은 경우","인증서 배포는 됐지만 적용(펌웨어 반영) 단계가 완료되지 않은 경우"],"checks":["설정 > Windows 업데이트에서 대기 중인 업데이트·재부팅이 있는지 확인하세요.","업데이트 기록에서 Secure Boot 관련 업데이트 적용 이력을 확인하세요.","메인보드·노트북 제조사 홈페이지에서 최신 BIOS·UEFI 펌웨어를 확인하고 적용하세요.","msinfo32를 실행해 보안 부팅 상태가 '켜짐'으로 유지되는지 확인하세요."],"warnings":["Secure Boot을 임의로 끄지 마세요. 인증서 갱신은 자동으로 진행되는 정상적인 보안 유지보수입니다.","펌웨어 업데이트 중 전원이 끊기면 메인보드가 손상될 수 있으니 노트북은 충전기를 연결한 채 진행하세요."],"relatedCodes":[],"relatedGuides":["windows-repair-tools-guide.html"],"detailPage":"event-tpm-wmi-1801.html"},{"id":"1040","source":"TPM-WMI","level":"error","urgency":"driver","summary":"장치 증명(어테스테이션) 사전 상태 검사에서 중요한 구성 요소가 실패해, 이 장치가 증명을 통과하지 못할 것으로 예상된다는 기록입니다. TPM-WMI 1801(펌웨어에 미적용된 Secure Boot 인증서)과 같은 시기에 나타나면 그 연장선일 수 있습니다.","conditions":["TPM-WMI 1801과 같은 시기에 기록","BitLocker·Windows Hello처럼 장치 증명이 필요한 기능 사용 중","MeasuredBoot 로그 폴더에 검사 결과 JSON 파일 생성"],"causes":["Secure Boot 인증서가 최신 상태로 갱신되지 않아 부팅 측정값이 예상과 달라진 경우","BIOS·UEFI 펌웨어가 오래되어 측정 부팅(Measured Boot) 체인이 기대값과 일치하지 않는 경우","TPM 펌웨어나 초기화 상태 자체의 결함"],"checks":["이벤트에 안내된 MeasuredBoot 로그 폴더의 JSON 파일에서 실패한 구성 요소를 확인하세요.","같은 시기에 TPM-WMI 1801(Secure Boot 인증서 미적용)이 함께 있는지 확인하세요.","메인보드·노트북 제조사 최신 BIOS로 업데이트한 뒤 재현 여부를 확인하세요.","BitLocker·Windows Hello 같은 실제 기능에 장애가 있는지 확인하세요 — 기능이 정상이라면 당장 조치가 급하지 않습니다."],"warnings":["이벤트 문구가 심각하게 보이지만, 실제 BitLocker·Windows Hello 기능에 장애가 없다면 즉시 초기화나 재설치를 진행하지 마세요.","TPM을 초기화하기 전에는 BitLocker 복구 키를 반드시 먼저 백업하세요."],"relatedCodes":[],"relatedGuides":["windows-repair-tools-guide.html"],"detailPage":"event-tpm-wmi-1040.html"},{"id":"1014","source":"DNS Client Events","sourceAliases":["Microsoft-Windows-DNS-Client","DNS Client"],"level":"warning","urgency":"driver","summary":"DNS 이름 확인 요청이 제한 시간 안에 응답하지 않았음을 나타냅니다. 인터넷 연결이 완전히 끊겼다는 뜻은 아니며, 이벤트에 기록된 도메인과 발생 시각을 함께 비교해야 합니다.","conditions":["웹사이트가 늦게 열리거나 특정 서비스만 접속되지 않음","와이파이 전환·절전 복귀 직후","게임 런처·Windows Update·시간 동기화가 서버를 찾지 못함","같은 도메인에 대한 1014가 짧은 시간에 반복됨"],"causes":["DNS 서버 지연 또는 일시적인 응답 실패","공유기·통신사 회선의 DNS 캐시·경로 문제","VPN·프록시·보안 프로그램의 DNS 필터 영향","무선랜 드라이버나 절전 복귀 과정에서 네트워크가 아직 준비되지 않음","회사·학교 네트워크의 DNS 정책 또는 특정 도메인 차단"],"checks":["이벤트의 QueryName(조회 도메인)과 발생 시각을 기록하고 같은 시간에 실제 접속 지연이 있었는지 비교","명령 프롬프트에서 ipconfig /flushdns 후 nslookup 조회도 지연되는지 확인","PowerShell에서 Resolve-DnsName 도메인명 -Server 1.1.1.1과 기본 DNS 결과를 비교","다른 사이트·장치·모바일 핫스팟에서도 재현되는지 확인해 PC 문제와 공유기·회선 문제를 구분","VPN·프록시·보안 필터를 임시로 분리한 뒤 재현 여부를 비교","1014와 같은 시각의 DHCP-Client 1001, Tcpip 4199·4266, WLAN-AutoConfig 이벤트를 함께 확인"],"warnings":["인터넷이 정상이고 단발성이면 하드웨어 고장으로 보지 마세요.","1014가 반복되어도 DNS 서버 응답 지연과 실제 회선 단절은 다를 수 있습니다. DHCP 이벤트나 169.254.x.x 주소가 함께 보이면 DNS 변경보다 IP·게이트웨이부터 점검하세요.","공용 DNS로 변경하기 전 회사·학교 네트워크 정책을 확인하고, 변경 전 기존 DNS 주소를 기록해 두세요."],"relatedCodes":["1001","4199","4266"],"relatedGuides":["hardware-wifi-disconnect.html","network-connection-guide.html","event-viewer-guide.html"],"detailPage":"event-dns-1014.html"},{"id":"1001","source":"DHCP-Client","sourceAliases":["Microsoft-Windows-DHCP-Client"],"level":"error","urgency":"driver","summary":"DHCP 클라이언트가 네트워크에서 IP 주소를 임대받거나 갱신하지 못했음을 기록합니다. 인터넷이 안 된다는 결과만으로 DNS 문제라고 단정하지 말고 IP·게이트웨이 할당부터 확인해야 합니다.","conditions":["부팅 후 인터넷 연결 안 됨","Wi-Fi·유선 전환 뒤 IP가 169.254로 표시","절전 복귀 후 네트워크 끊김"],"causes":["공유기·DHCP 서버 응답 실패","랜 케이블·무선 링크 불안정","네트워크 어댑터 드라이버·절전 설정","VPN·가상 네트워크 어댑터 충돌"],"checks":["ipconfig /all에서 IPv4, 기본 게이트웨이, DHCP 서버 주소 확인","같은 공유기의 다른 기기도 IP를 받는지 비교","어댑터를 껐다 켜고 ipconfig /release·ipconfig /renew 실행","다른 케이블·포트와 최신 네트워크 드라이버로 교차 확인"],"warnings":["169.254.x.x 주소가 보이면 DNS를 바꾸기 전에 DHCP·케이블·공유기부터 확인하세요."],"relatedCodes":[],"relatedGuides":["network-connection-guide.html","hardware-wifi-disconnect.html"],"detailPage":"event-viewer-guide.html"},{"id":"10002","source":"WLAN-AutoConfig","sourceAliases":["Microsoft-Windows-WLAN-AutoConfig"],"level":"warning","urgency":"driver","summary":"무선랜 확장 모듈이 중지되었음을 기록합니다. 보통 무선 드라이버나 제조사 확장 모듈의 재시작 과정에서 나타나므로, Wi-Fi 연결 끊김과 같은 시각인지 먼저 확인합니다.","conditions":["Wi-Fi 연결 끊김·재연결","절전 복귀 후 무선랜 불안정","드라이버 업데이트나 무선 네트워크 전환 직후"],"causes":["무선랜 드라이버·확장 모듈 충돌","제조사 무선 유틸리티와 Windows WLAN 서비스 충돌","어댑터 전원 관리 또는 절전 복귀 문제","공유기 전환 중 일시적인 링크 변화"],"checks":["이벤트의 Module Path와 무선 어댑터 모델 기록","장치 관리자에서 무선 드라이버 버전 확인","제조사 드라이버로 업데이트·롤백하고 무선 관리 유틸리티 충돌 여부 비교","Wi-Fi 연결이 정상이고 단발성이면 오류 누적만으로 드라이버를 삭제하지 않기"],"warnings":["10002가 있다는 사실만으로 무선랜 카드 고장을 확정하지 마세요. 실제 연결 끊김과 반복 시각이 일치해야 합니다."],"relatedCodes":[],"relatedGuides":["network-connection-guide.html","hardware-wifi-disconnect.html"],"detailPage":"event-viewer-guide.html"},{"id":"27","source":"e2fexpress","level":"warning","urgency":"driver","summary":"Intel 유선 네트워크 어댑터의 링크가 끊기거나 드라이버가 연결 변화를 기록한 경우가 많습니다.","conditions":["랜 연결 끊김","절전 복귀 뒤 네트워크 없음"],"causes":["케이블·공유기 포트","어댑터 전원 관리","네트워크 드라이버"],"checks":["이벤트 설명의 링크 상태 확인","케이블·포트 교차","전원 관리와 제조사 드라이버 점검"],"warnings":["원본 이름은 어댑터 모델에 따라 달라질 수 있습니다."],"relatedCodes":["0x0000009F"],"relatedGuides":["hardware-wifi-disconnect.html"],"detailPage":"event-e2fexpress-27.html"},{"id":"32","source":"e2fexpress","level":"warning","urgency":"driver","summary":"유선 네트워크 드라이버가 링크 또는 장치 상태 문제를 보고한 기록으로 나타날 수 있습니다.","conditions":["부팅 후 네트워크 연결 지연","대용량 전송 중 끊김"],"causes":["랜 케이블·포트","드라이버·절전 설정","공유기 협상 문제"],"checks":["이벤트 원문과 어댑터 이름 확인","링크 속도·케이블 비교","드라이버와 절전 설정 점검"],"warnings":["이벤트 ID만 같고 원본이 다르면 의미도 달라질 수 있습니다."],"relatedCodes":[],"relatedGuides":["hardware-wifi-disconnect.html"],"detailPage":"event-e2fexpress-32.html"},{"id":"11","source":"Disk","level":"error","urgency":"backup","summary":"디스크 컨트롤러가 디스크 장치에서 오류를 감지했다는 기록입니다. 이벤트 7과 함께 나타날 경우 저장장치 이상 신호로 봐야 합니다.","conditions":["파일 복사 중 멈춤","특정 드라이브 접근 시 지연","부팅 중 디스크 인식 오류"],"causes":["SATA 케이블·포트 접촉 불량","저장장치 컨트롤러 오류","M.2 또는 SATA SSD 펌웨어 문제"],"checks":["오류에 표시된 디스크 번호 확인","SATA 케이블 교체 또는 포트 변경","제조사 진단 도구로 디스크 건강 상태 확인"],"warnings":["이벤트 7과 함께 반복되면 즉시 데이터를 백업하세요."],"relatedCodes":["0x0000007A","0x00000077"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-disk-11.html"},{"id":"9","source":"Disk","level":"warning","urgency":"backup","summary":"디스크 드라이버가 \\Device\\Harddisk 장치에서 컨트롤러 오류를 감지했다는 기록입니다. 연결 문제와 하드웨어 오류 모두 원인이 될 수 있습니다.","conditions":["디스크 접근 중 지연","외장 드라이브 연결 시 오류","RAID 구성에서 장치 인식 실패"],"causes":["USB 또는 SATA 연결 불량","전원 공급 부족","저장장치 컨트롤러 또는 케이블 불량"],"checks":["디스크 인스턴스 번호로 어떤 장치인지 확인","케이블과 연결 상태 점검","다른 포트로 이동 후 재현 여부 확인"],"warnings":["반복 발생 시 데이터 백업을 먼저 진행하세요."],"relatedCodes":["0x0000007A"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-disk-9.html"},{"id":"50","source":"Ntfs","level":"warning","urgency":"backup","summary":"NTFS가 저장장치에 데이터를 쓰려다 실패했음을 나타냅니다. 쓰기 작업이 지연되다가 실패하는 '지연 쓰기 실패' 상황입니다.","conditions":["파일 저장 직후 오류 메시지","외장 드라이브 분리 후 데이터 손실","전원 불안정 상황에서의 쓰기 작업"],"causes":["저장장치 응답 시간 초과","케이블 또는 연결 불안정","전원 관리로 인한 장치 슬립"],"checks":["해당 볼륨 레이블 확인 후 대상 드라이브 특정","케이블 상태와 전원 관리 설정 점검","SMART 및 제조사 진단 도구로 건강 상태 확인"],"warnings":["쓰기 실패 후 파일이 손상됐을 수 있으므로 저장된 데이터를 확인하세요."],"relatedCodes":["0x00000024","0x0000007A"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-ntfs-50.html"},{"id":"57","source":"Ntfs","level":"error","urgency":"backup","summary":"NTFS 파일 시스템 메타데이터 쓰기가 실패했음을 나타냅니다. 파일 시스템 구조 자체의 무결성이 위협받는 상태입니다.","conditions":["비정상 종료 뒤","외장 드라이브에서 쓰기 오류","저장장치 응답이 느릴 때"],"causes":["저장장치 응답 불량","케이블 또는 컨트롤러 문제","전원 공급 불안정"],"checks":["발생 즉시 데이터 백업 진행","이벤트 55와 함께 나타나는지 확인","SMART 확인 후 디스크 교체 여부 판단"],"warnings":["이 이벤트가 반복되면 저장장치 교체를 심각하게 고려하세요."],"relatedCodes":["0x00000024"],"relatedGuides":["hardware-nvme-delay.html"],"detailPage":"event-ntfs-57.html"},{"id":"157","source":"Disk","level":"warning","urgency":"driver","summary":"운영 체제가 종료 절차 없이 디스크가 갑자기 제거됐음을 감지한 기록입니다.","conditions":["외장 드라이브 갑작스러운 분리","USB 연결 중 전원 차단","노트북 배터리 방전으로 강제 종료"],"causes":["안전 제거 없이 장치 분리","USB 케이블 접촉 불량","배터리 방전 또는 전원 오류"],"checks":["외장 장치는 항상 안전 제거 사용","케이블과 포트 상태 확인","파일 시스템 손상 여부 확인(chkdsk)"],"warnings":["강제 분리로 파일 손상이 발생했을 수 있습니다. 중요 파일부터 확인하세요."],"relatedCodes":["0x8007045D"],"relatedGuides":["hardware-usb-not-detected.html"],"detailPage":"event-disk-157.html"},{"id":"4625","source":"Security","sourceAliases":["Microsoft-Windows-Security-Auditing"],"level":"error","urgency":"repeat-check","summary":"계정이 로그온에 실패했음을 기록합니다. 반복되면 잘못된 비밀번호 입력, 계정 잠금, 또는 외부 접근 시도를 나타낼 수 있습니다.","conditions":["로그인 실패 메시지","도메인 계정 접근 오류","원격 데스크톱 연결 실패"],"causes":["비밀번호 오입력 반복","CapsLock 또는 한영 전환 문제","저장된 자격 증명 만료","외부 무차별 대입 시도"],"checks":["실패 이유 코드(0xC000006D 등)와 로그온 유형 확인","특정 계정만 반복 실패하는지 확인","원격 접근이면 소스 IP 확인"],"warnings":["같은 계정의 반복 실패가 짧은 시간에 몰린다면 보안 위협일 수 있습니다."],"relatedCodes":[],"relatedGuides":["windows-ms-account-login-fail.html"],"detailPage":"event-security-4625.html"},{"id":"4740","source":"Security","sourceAliases":["Microsoft-Windows-Security-Auditing"],"level":"error","urgency":"repeat-check","summary":"사용자 계정이 잠겼음을 기록합니다. 반복 로그인 실패 또는 만료된 자격 증명이 자동으로 재시도되고 있는 경우입니다.","conditions":["로그인 시 계정 잠금 메시지","도메인 연결 PC에서 접근 불가","저장된 자격 증명이 있는 앱에서 오류"],"causes":["여러 장치에서 동일 계정 만료 비밀번호 자동 재시도","자격 증명 관리자의 오래된 비밀번호","스케줄 작업 또는 서비스의 만료 자격 증명"],"checks":["이벤트의 호출자 PC 이름으로 잠금 원인 장치 찾기","자격 증명 관리자에서 해당 계정 항목 삭제·갱신","예약 작업과 서비스의 실행 계정 비밀번호 갱신"],"warnings":["반복 잠금은 만료된 자격 증명이 여러 장소에 저장된 경우가 많습니다."],"relatedCodes":[],"relatedGuides":["windows-ms-account-login-fail.html"],"detailPage":"event-security-4740.html"},{"id":"8193","source":"VSS","level":"error","urgency":"driver","summary":"볼륨 섀도 복사본 서비스(VSS)가 오류로 실패했음을 기록합니다. 백업 소프트웨어와 시스템 복원 지점 생성에 영향을 줍니다.","conditions":["시스템 복원 지점 생성 실패","백업 소프트웨어 오류","Windows Server 백업 실패"],"causes":["디스크 공간 부족","VSS 서비스 또는 작성기 오류","백업 중 저장장치 응답 지연"],"checks":["이벤트 설명의 오류 코드 확인","그림자 복사본 스토리지 여유 공간 확인","vssadmin list writers 명령으로 작성기 상태 확인"],"warnings":["이 이벤트 반복 시 시스템 복원 지점이 만들어지지 않고 있을 수 있습니다."],"relatedCodes":["0x80070070"],"relatedGuides":["windows-update-fail-loop.html"],"detailPage":"event-vss-8193.html"},{"id":"6013","source":"EventLog","level":"information","urgency":"info","summary":"시스템 부팅 이후 경과한 시간(시스템 가동 시간, 업타임)을 초 단위로 기록합니다. 매일 한 번 생성되는 정보성 이벤트입니다.","conditions":["정기적으로 매일 생성됨"],"causes":["정상 동작 — 매일 자동 기록"],"checks":["가동 시간이 매우 짧다면 예상치 못한 재부팅이 있었는지 확인","같은 날짜의 Kernel-Power 41 이벤트와 비교"],"warnings":["정보성 이벤트로, 단독으로는 문제가 아닙니다."],"relatedCodes":[],"relatedGuides":["hardware-gaming-reboot.html"],"detailPage":"event-eventlog-6013.html"},{"id":"1102","source":"Security","sourceAliases":["Microsoft-Windows-Security-Auditing"],"level":"information","urgency":"repeat-check","summary":"감사 로그가 지워졌음을 기록합니다. 관리 목적으로 지우는 경우도 있지만, 침해 사고 후 흔적 삭제 시도로도 나타납니다.","conditions":["보안 이벤트 로그 초기화 후","악성 소프트웨어 감염 의심 상황"],"causes":["관리자의 의도적인 로그 삭제","악성 소프트웨어에 의한 로그 삭제"],"checks":["로그를 삭제한 계정 이름과 시각 확인","삭제 전후 비정상적인 로그인 또는 실행 흔적 비교","의도치 않은 삭제라면 보안 점검을 진행하세요"],"warnings":["의도하지 않은 보안 로그 삭제는 보안 사고의 신호일 수 있습니다."],"relatedCodes":[],"relatedGuides":["windows-ms-account-login-fail.html"],"detailPage":"event-security-1102.html"},{"id":"1530","source":"User Profile Service","sourceAliases":["Microsoft-Windows-User Profiles Service","profsvc"],"level":"warning","urgency":"info","summary":"로그오프 과정에서 앱이나 서비스가 사용자 레지스트리 하이브의 핸들을 닫지 않아 Windows가 대신 정리한 기록입니다. Microsoft 문서상 설계된 동작이며, 실제 로그오프 지연이나 앱 종료 문제가 있을 때 원인을 좁히는 단서가 됩니다.","conditions":["로그오프·종료가 늦어짐","특정 앱을 닫은 뒤 반복","기능 장애 없이 경고만 누적"],"causes":["백그라운드 앱이 사용자 설정을 계속 사용하는 경우","오래된 프로그램·서비스가 로그오프 이벤트에 제대로 응답하지 않는 경우","보안·동기화·백업 프로그램의 종료 지연"],"checks":["이벤트에 표시된 프로세스 이름과 발생 시각 기록","로그오프가 실제로 지연되는지 확인","해당 앱 업데이트·종료 설정과 클린 부팅에서 재현 여부 비교","기능 장애가 없으면 이벤트 수를 줄이려고 레지스트리를 수정하지 않기"],"warnings":["1530만으로 메모리 누수나 사용자 프로필 손상을 확정하지 마세요. 단독·일회성 경고는 대개 긴급하지 않습니다."],"relatedCodes":[],"relatedGuides":["windows-startup-slow.html","windows-clean-boot-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"36874","source":"Schannel","level":"error","urgency":"driver","summary":"TLS 연결에서 클라이언트와 서버가 공통으로 사용할 암호화 방식이나 프로토콜을 찾지 못해 연결이 실패했음을 기록합니다.","conditions":["특정 웹사이트·업데이트 서버 연결 실패","오래된 프로그램의 HTTPS 통신 오류","인증서·TLS 설정 변경 직후"],"causes":["클라이언트와 서버의 TLS 버전·암호화 스위트 불일치","오래된 앱·프록시·보안 장비의 TLS 호환성 문제","인증서 체인 또는 시스템 시간 오류"],"checks":["이벤트의 Protocol·오류 상태·호출 프로세스 확인","같은 시각 36888과 앱·Windows Update 실패 여부 비교","시스템 날짜·시간과 루트 인증서 업데이트 확인","앱·프록시·서버가 지원하는 TLS 설정을 공식 문서 기준으로 비교"],"warnings":["보안을 낮추기 위해 TLS 1.0·1.1을 무조건 활성화하거나 Schannel 로그만 숨기지 마세요.","서버를 운영한다면 클라이언트와 서버 양쪽 설정을 함께 확인해야 합니다."],"relatedCodes":["0x80072F8F","0x80072EE2"],"relatedGuides":["windows-ms-account-login-fail.html","windows-update-fail-loop.html"],"detailPage":"event-viewer-guide.html"},{"id":"36887","source":"Schannel","level":"error","urgency":"driver","summary":"원격 끝점(서버)이 이 PC와의 TLS 핸드셰이크를 거부하며 치명적 경고를 보내왔음을 기록합니다. 36888(이 PC가 보낸 경고)과 반대 방향의 기록입니다.","conditions":["특정 사이트·서버 접속 실패","VPN·프록시·백신 HTTPS 검사 사용 중","36874와 같은 시각에 반복"],"causes":["서버가 이 PC의 TLS 버전·암호화 스위트를 지원하지 않는 경우","인증서가 만료됐거나 신뢰할 수 없는 경우","백신·VPN의 HTTPS 검사가 핸드셰이크를 가로채 서버 쪽에서 거부하는 경우","시스템 날짜·시간 오류로 인증서 유효기간 검증이 실패하는 경우"],"checks":["이벤트 설명의 fatal alert 코드와 PID 확인 (다른 PC의 로그를 열람 중이면 값 대신 %1·%3로 표시될 수 있음)","날짜·시간 자동 설정이 켜져 있는지 확인","백신·VPN의 HTTPS 검사 기능을 잠시 끄고 재현 여부 비교","브라우저·Windows를 최신 버전으로 업데이트해 TLS 지원 범위 확인"],"warnings":["36887은 상대 서버가 보낸 결과 기록일 뿐, 이 PC가 해킹당했다는 뜻이 아닙니다.","보안을 낮추기 위해 백신 HTTPS 검사를 계속 꺼두지 마세요."],"relatedCodes":["0x80072F8F"],"relatedGuides":["windows-ms-account-login-fail.html"],"detailPage":"event-schannel-36887.html"},{"id":"36888","source":"Schannel","level":"error","urgency":"driver","summary":"TLS 핸드셰이크 중 치명적 경고가 발생해 보안 연결이 종료됐음을 기록합니다. 36874와 함께 나타나면 협상 실패의 결과인지 먼저 확인합니다.","conditions":["HTTPS 로그인·동기화 실패","브라우저나 백그라운드 서비스의 연결 오류","36874와 같은 시각에 반복"],"causes":["원격 서버가 보낸 TLS fatal alert","지원하지 않는 TLS 프로토콜·암호화 스위트","잘못된 인증서·프록시·검사형 보안 프로그램"],"checks":["fatal alert 번호와 내부 상태 코드를 기록","36874·앱 오류·Windows Update 오류의 발생 시각 비교","시스템 시간·인증서·프록시 설정을 확인","문제가 특정 앱에만 있으면 그 앱의 TLS·인증서 지원 범위를 먼저 확인"],"warnings":["이벤트 36888은 연결 실패의 결과일 수 있으므로 단독으로 악성 공격이나 PC 고장으로 판단하지 마세요."],"relatedCodes":["0x80072F8F"],"relatedGuides":["windows-ms-account-login-fail.html"],"detailPage":"event-viewer-guide.html"},{"id":"7045","source":"Service Control Manager","level":"information","urgency":"repeat-check","summary":"Windows에 새 서비스 또는 커널 드라이버 서비스가 설치되었음을 기록합니다. 정상적인 드라이버·보안 프로그램 설치에도 발생하지만, 모르는 실행 파일 경로가 보이면 보안 확인이 필요합니다.","conditions":["드라이버·프로그램 설치 직후","예상하지 못한 서비스 생성","재부팅·보안 이상과 같은 시각"],"causes":["정상 프로그램·드라이버 설치","Windows Defender 정의 업데이트","관리 도구·업데이트 작업","사용자가 모르는 프로그램의 지속성 확보 시도"],"checks":["서비스 이름·서비스 파일 경로·계정·시작 유형 기록","설치한 프로그램·드라이버와 시각이 일치하는지 확인","파일 서명과 게시자 확인","예상하지 못한 항목이면 네트워크 연결을 보존한 채 보안 검사와 최근 설치 목록을 점검"],"warnings":["7045는 오류가 아니라 설치 감사 기록입니다. Microsoft·제조사 경로라도 이름이 낯설 수 있으므로 파일 서명과 경로를 함께 확인하세요.","서비스를 바로 삭제하거나 비활성화하기 전에 복구 방법과 설치 주체를 확인하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","windows-clean-boot-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"7040","source":"Service Control Manager","level":"information","urgency":"info","summary":"Windows 서비스의 시작 유형이 변경되었음을 기록합니다. Windows 업데이트·드라이버 설치·관리 도구로도 발생할 수 있어 변경 주체와 실제 기능 장애를 함께 확인해야 합니다.","conditions":["드라이버·보안 프로그램 설치 또는 업데이트 뒤","서비스가 자동·수동·사용 안 함으로 바뀐 뒤","부팅 후 특정 기능이 동작하지 않음"],"causes":["정상적인 프로그램·드라이버 설치","Windows 구성 요소 업데이트","클린 부팅이나 사용자의 서비스 설정 변경","원치 않는 프로그램이 보안·업데이트 서비스를 끄는 경우"],"checks":["이벤트의 서비스 이름과 이전·새 시작 유형 기록","변경 시각의 설치 기록·Windows Update·보안 이벤트 비교","서비스가 실제로 필요한 기능과 연결되는지 확인","예상하지 못한 보안 서비스 변경이면 Defender 상태와 최근 설치 프로그램을 점검"],"warnings":["7040은 오류가 아닌 구성 변경 기록입니다. 모든 서비스를 자동 시작으로 되돌리면 부팅 지연이나 충돌이 생길 수 있습니다."],"relatedCodes":["0x80070422"],"relatedGuides":["windows-clean-boot-guide.html","windows-app-not-launching.html"],"detailPage":"event-viewer-guide.html"},{"id":"4266","source":"Tcpip","sourceAliases":["TCPIP","Microsoft-Windows-TCPIP"],"level":"error","urgency":"repeat-check","summary":"TCP/IP 네트워크 스택이 연결 또는 소켓 처리 과정에서 오류를 기록한 이벤트입니다. 4266만으로 랜카드 고장을 확정할 수 없으며, 일반 탭의 오류 문장과 XML에 있는 인터페이스·주소·오류 코드를 함께 봐야 의미를 좁힐 수 있습니다.","conditions":["네트워크 연결이 끊겼다가 다시 연결됨","VPN·가상 어댑터를 연결하거나 해제한 직후","대용량 전송·게임·원격 접속 중 네트워크 오류"],"causes":["네트워크 어댑터 드라이버 또는 필터 드라이버 충돌","VPN·가상 스위치·보안 프로그램의 네트워크 필터","TCP/IP 설정·IPv4/IPv6·오프로드 기능의 호환성","공유기·케이블·무선 링크의 일시적인 연결 문제"],"checks":["일반 탭과 XML에서 ErrorCode·인터페이스 이름·로컬/원격 주소를 기록","같은 시각의 4199·DHCP 1001·DNS 1014·네트워크 드라이버 이벤트와 비교","ipconfig /all과 Get-NetIPConfiguration으로 주소·게이트웨이·어댑터 상태 확인","VPN·가상 네트워크·보안 필터를 잠시 분리하고 제조사 네트워크 드라이버로 재현 여부 비교","끊김이 계속되면 케이블·공유기 포트·다른 네트워크에서 교차 확인"],"warnings":["4266의 ID만 보고 TCP/IP 초기화나 랜카드 교체부터 진행하지 마세요. 실제 연결 장애와 이벤트 발생 시각이 일치하는지 먼저 확인하세요."],"relatedCodes":[],"relatedGuides":["network-connection-guide.html","hardware-wifi-disconnect.html"],"detailPage":"event-tcpip-4266.html"},{"id":"30","source":"TPM","sourceAliases":["TPM-WMI","Microsoft-Windows-TPM-WMI"],"level":"warning","urgency":"driver","summary":"TPM 공급자 또는 TPM 관리 구성 요소가 보안 칩의 상태·키·기능을 처리하는 과정에서 남기는 기록입니다. Windows Hello·BitLocker·보안 부팅 문제가 함께 있을 때 세부 메시지와 펌웨어 상태를 확인해야 합니다.","conditions":["로그인 PIN·Windows Hello 설정 또는 사용 중","BitLocker 보호 상태 변경 뒤","BIOS 업데이트·TPM 설정 변경·메인보드 교체 뒤"],"causes":["BIOS/UEFI의 TPM·Intel PTT·AMD fTPM 설정 또는 펌웨어 문제","TPM 소유권·프로비저닝·Windows Hello 키 상태 불일치","TPM WMI 공급자나 관련 Windows 구성 요소의 일시적 오류"],"checks":["이벤트 일반 탭과 XML에서 오류 상태·명령·TPM 버전 정보를 기록","tpm.msc와 PowerShell Get-Tpm으로 TPM 준비 상태와 보호 상태 확인","메인보드 제조사의 BIOS·칩셋 업데이트와 TPM 관련 변경 내역 확인","BitLocker 복구 키와 다른 로그인 수단을 확보한 뒤에만 TPM 초기화를 검토","Windows Hello·BitLocker 문제가 없다면 단발성 기록인지 반복 여부를 먼저 관찰"],"warnings":["TPM 지우기는 BitLocker 복구 키가 없으면 드라이브 접근에 문제가 생길 수 있습니다. 복구 키 확인 전에는 초기화하지 마세요.","이벤트 30만으로 TPM 칩 고장이나 보안 침해를 단정하지 마세요."],"relatedCodes":[],"relatedGuides":["windows-11-upgrade-blocked.html","event-viewer-guide.html"],"detailPage":"event-tpm-30.html"},{"id":"154","source":"Disk","level":"error","urgency":"backup","summary":"Disk 계층의 입출력 작업이 하드웨어 오류로 실패했음을 나타내는 기록입니다. 서버·FC 저장장치에서는 어댑터·컨트롤러·저장장치 배열의 통신 문제로도 발생하며, 일반 PC에서는 디스크·컨트롤러·케이블·슬롯과 펌웨어를 함께 확인해야 합니다.","conditions":["파일 복사·저장 중 멈춤 또는 지연","부팅·프로그램 실행 중 저장장치 접근 오류","Disk 7·11·51·129·153 또는 Ntfs 이벤트가 같은 시간에 반복"],"causes":["저장장치 또는 컨트롤러의 I/O 시간 초과","SATA 케이블·전원·M.2 슬롯 접촉 문제","SSD·HDD 펌웨어와 칩셋·스토리지 드라이버 문제","서버·FC 환경의 링크·어댑터·스토리지 배열 통신 오류"],"checks":["중요 파일을 다른 저장장치에 먼저 백업","이벤트의 디스크 번호·LBA·포트·오류 문장을 기록해 대상 장치 특정","SMART와 제조사 진단 도구로 건강 상태·온도·미디어 오류 확인","SATA 케이블·전원·M.2 장착 상태를 점검하고 다른 포트·슬롯으로 교차 확인","Disk·Ntfs·storahci·WHEA 이벤트를 같은 시각으로 묶어 반복 조건을 비교","서버·FC 환경이면 어댑터·스위치·스토리지 제조사 로그와 펌웨어를 함께 점검"],"warnings":["반복되는 154에서는 복구 명령이나 레지스트리의 디스크 시간 제한 값을 먼저 바꾸지 마세요. 데이터 백업과 하드웨어 경로 확인이 우선입니다."],"relatedCodes":["0x0000007A","0x00000077"],"relatedGuides":["hardware-nvme-delay.html","event-viewer-guide.html"],"detailPage":"event-disk-154.html"},{"id":"4199","source":"Tcpip","sourceAliases":["TCPIP","Microsoft-Windows-TCPIP"],"level":"error","urgency":"repeat-check","summary":"TCP/IP가 같은 네트워크에서 IP 주소 충돌을 감지했음을 나타내는 이벤트입니다. DHCP 주소를 받는 과정의 중복 감지나 IPv4·IPv6 주소 충돌로 기록될 수 있으며, 일반 탭에 표시된 충돌 주소와 네트워크 하드웨어 주소가 핵심 단서입니다.","conditions":["부팅·절전 복귀 후 인터넷이 되지 않음","IP 주소 충돌 알림이나 연결 끊김","DHCP 갱신·공유기 재시작·VPN 연결 직후"],"causes":["공유기·DHCP 서버가 이미 사용 중인 주소를 임대하는 경우","고정 IP와 DHCP 주소가 겹치는 경우","절전 복귀·VPN·가상 어댑터 전환 중 중복 주소가 감지되는 경우","공유기 펌웨어나 네트워크 장치의 주소 관리 문제"],"checks":["일반 탭과 XML에서 충돌한 IP 주소·상대 하드웨어 주소·어댑터 이름을 기록","ipconfig /all로 DHCP 사용 여부와 현재 주소를 확인하고 고정 IP 중복 여부 점검","공유기 관리 화면에서 DHCP 임대 목록과 고정 할당을 비교","VPN·가상 어댑터를 끈 상태와 다른 공유기·케이블에서 재현 여부 비교","반복되면 PC·공유기 펌웨어와 네트워크 드라이버를 업데이트하고 DHCP 임대 정보를 재검토"],"warnings":["한두 번 발생하고 인터넷 사용에 문제가 없다면 일시적인 중복 감지일 수 있습니다. 반복적인 끊김이 있을 때만 주소 할당 구성을 조정하세요.","같은 IP를 임의로 고정하거나 DHCP 범위를 줄이기 전에 현재 네트워크의 다른 장치 구성을 확인하세요."],"relatedCodes":[],"relatedGuides":["network-connection-guide.html","hardware-wifi-disconnect.html"],"detailPage":"event-tcpip-4199.html"},{"id":"36","source":"volsnap","sourceAliases":["Volsnap","Microsoft-Windows-Volsnap"],"level":"error","urgency":"repeat-check","summary":"볼륨 섀도 복사본이 지정된 섀도 복사본 저장 영역 제한 때문에 중단됐다는 기록입니다. 시스템 복원·Windows 백업·백업 프로그램이 새 복사본을 만들지 못할 수 있지만, 일반 디스크 여유 공간과 섀도 복사본 전용 한도는 별도로 확인해야 합니다.","conditions":["시스템 복원 지점 생성 실패","Windows 백업·백업 프로그램 오류","volsnap 36이 특정 볼륨에서 반복"],"causes":["섀도 복사본 저장 영역의 사용자 지정 최대 크기 초과","복원 지점·백업 작업이 짧은 시간에 많이 쌓인 경우","원본 볼륨의 I/O 지연이나 Disk·Ntfs 오류","VSS 작성기·백업 공급자 또는 저장장치 상태 문제"],"checks":["이벤트에 표시된 원본 볼륨과 중단된 섀도 복사본 번호 기록","vssadmin list shadowstorage와 vssadmin list shadows로 전용 저장 영역과 기존 복사본 확인","시스템 보호 설정에서 해당 볼륨의 최대 사용량과 실제 복원 지점 필요 여부 확인","같은 시각의 VSS·Disk·Ntfs·storahci 이벤트를 비교","백업이 필요한 환경이면 기존 복구 지점을 지우기 전에 대체 백업이 정상인지 확인"],"warnings":["일반 디스크에 여유 공간이 많아도 섀도 복사본 전용 한도는 부족할 수 있습니다.","vssadmin delete shadows /all을 무심코 실행하면 기존 복원 지점과 백업 복사본이 삭제될 수 있으므로 먼저 대상과 복구 계획을 확인하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-nvme-delay.html"],"detailPage":"event-volsnap-36.html"},{"id":"100","source":"winsrvext","sourceAliases":["WinSrvExt","Microsoft-Windows-WinSrvExt"],"level":"warning","urgency":"info","summary":"winsrvext 확장 구성 요소가 Windows 서버·세션 관련 작업 중 남기는 기록입니다. 이벤트 ID만으로 의미를 확정하기 어렵고, 원격 데스크톱·서버 역할·로그온 세션과 관련된 일반 탭 문장 및 XML을 함께 해석해야 합니다.","conditions":["원격 데스크톱·터미널 세션 연결 또는 종료 뒤","서버 역할이나 세션 기반 기능 사용 중","기능 장애 없이 시스템 로그에 단발성 기록"],"causes":["Windows 세션·원격 데스크톱 확장 구성 요소의 일시적인 상태 기록","서버 역할·RDS 구성 또는 관련 서비스의 변경","최근 Windows 업데이트·드라이버·세션 관리 프로그램의 호환성 문제"],"checks":["이벤트 일반 탭과 XML에서 Message·Task·세션·컴퓨터 역할 정보를 먼저 기록","발생 시각의 원격 데스크톱·TerminalServices·Service Control Manager 이벤트와 비교","실제 로그인·원격 세션 끊김·앱 실행 장애가 있는지 확인","서버 역할이나 RDS를 사용한다면 관련 서비스 상태와 최근 업데이트를 확인","증상 없이 단발성이라면 조치보다 반복 여부와 기능 영향 관찰"],"warnings":["winsrvext 100은 구성과 Windows 버전에 따라 세부 의미가 달라질 수 있습니다. 이벤트 ID만으로 하드웨어 고장이나 보안 문제로 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","windows-startup-slow.html"],"detailPage":"event-winsrvext-100.html"},{"id":"10110","source":"DriverFrameworks-UserMode","sourceAliases":["Microsoft-Windows-DriverFrameworks-UserMode","DriverFrameworks-UserMode"],"level":"critical","urgency":"repeat-check","summary":"사용자 모드 드라이버를 호스팅하던 프로세스에 문제가 생겨 하나 이상의 장치가 잠시 중단될 수 있음을 기록합니다. USB·오디오·HID·블루투스 장치에서 나타날 수 있으며, 10110 자체가 특정 장치 고장을 확정하는 것은 아닙니다.","conditions":["USB·헤드셋·블루투스 장치가 사라지거나 재연결됨","오디오가 끊기거나 입력 장치가 잠시 멈춤","절전 복귀·게임 실행·장치 연결 직후"],"causes":["장치 드라이버 또는 제조사 제어 프로그램 충돌","USB 허브·케이블·전원 관리 문제","오래된 칩셋·오디오·블루투스 드라이버","절전 복귀 과정에서 UMDF 호스트가 장치를 다시 초기화하지 못한 경우"],"checks":["XML에서 LifetimeId·Problem·ExitCode와 발생 시각을 기록","같은 시각의 10111에서 장치 이름·InstanceId·재시작 횟수 확인","장치 관리자에서 해당 장치의 드라이버 버전과 오류 상태 확인","허브를 거치지 않고 다른 포트·케이블·장치로 교차 확인","제조사 드라이버로 업데이트하거나 최근 업데이트 직후라면 롤백하고 절전 복귀 재현 여부 비교"],"warnings":["10110만으로 메인보드나 USB 컨트롤러 고장을 단정하지 마세요. 10111의 장치 정보와 실제 기능 장애가 핵심 단서입니다.","반복되는 장치가 있으면 작업 중인 파일을 저장한 뒤 드라이버를 변경하세요."],"relatedCodes":["0x0000009F"],"relatedGuides":["hardware-usb-not-detected.html","hardware-sound-not-working.html","windows-sleep-resume-fail.html"],"detailPage":"event-driverframeworks-10110.html"},{"id":"10111","source":"DriverFrameworks-UserMode","sourceAliases":["Microsoft-Windows-DriverFrameworks-UserMode","DriverFrameworks-UserMode"],"level":"critical","urgency":"repeat-check","summary":"사용자 모드 드라이버 충돌로 특정 장치가 오프라인 상태가 되었고 Windows가 장치를 다시 시작하려 했다는 기록입니다. 일반 탭의 장치 이름과 XML의 InstanceId·RestartCount를 이용하면 점검 대상을 구체적으로 찾을 수 있습니다.","conditions":["특정 장치가 장치 관리자에서 사라짐","헤드셋·웹캠·키보드·마우스·USB 장치가 끊김","10110 직후 같은 장치가 반복해서 오프라인이 됨"],"causes":["해당 장치의 UMDF 드라이버 또는 제조사 유틸리티 충돌","USB·블루투스 전원 관리와 절전 복귀 문제","케이블·허브·포트 접촉 불량","장치 펌웨어와 Windows 빌드의 호환성 문제"],"checks":["이벤트 XML의 FriendlyName·InstanceId·RestartCount를 기록해 장치를 특정","10110과 발생 시각을 맞춰 UMDF 호스트 오류의 선후 관계 확인","장치를 다른 포트·케이블·PC에 연결해 본체와 주변 환경을 분리","장치 제조사 드라이버·펌웨어와 칩셋 드라이버를 확인","전원 관리에서 장치 끄기 옵션을 비교하고 재현이 계속되면 장치 교체 테스트"],"warnings":["장치가 한 번 재연결되고 기능이 정상이라면 즉시 교체할 필요는 없습니다. RestartCount와 실제 끊김 반복을 함께 보세요.","InstanceId에는 장치 식별 정보가 포함될 수 있으므로 공유할 때는 일부를 가리고 전달하세요."],"relatedCodes":["0x0000009F"],"relatedGuides":["hardware-usb-not-detected.html","hardware-sound-not-working.html"],"detailPage":"event-driverframeworks-10111.html"},{"id":"2004","source":"Resource-Exhaustion-Detector","sourceAliases":["Microsoft-Windows-Resource-Exhaustion-Detector"],"level":"warning","urgency":"repeat-check","summary":"Windows가 시스템의 가상 메모리·커밋 한도가 부족한 상태를 진단했다는 경고입니다. 이벤트 설명에는 당시 커밋 메모리를 많이 사용한 프로세스가 포함될 수 있어, 단순한 RAM 사용률보다 커밋 크기와 페이지 파일을 확인해야 합니다.","conditions":["프로그램이 갑자기 종료되거나 응답하지 않음","게임·브라우저·가상 머신을 오래 실행한 뒤 메모리 부족","작업 관리자에서 커밋 사용량이 한도에 가까움"],"causes":["특정 프로그램·서비스의 가상 메모리 누수","페이지 파일이 꺼졌거나 크기가 지나치게 제한된 경우","여러 대형 프로그램을 동시에 실행해 커밋 한도를 초과한 경우","RAM 부족이 페이지 파일 사용 증가와 함께 나타난 경우"],"checks":["이벤트 설명에서 당시 상위 메모리 사용 프로세스와 사용량을 기록","작업 관리자 성능·메모리에서 커밋 사용량과 커밋 한도를 확인","설정의 페이지 파일이 자동 관리인지와 시스템 드라이브 여유 공간 확인","같은 프로그램이 재실행할수록 커밋을 계속 늘리는지 작업 관리자에서 비교","프로그램 업데이트·플러그인 제거·재시작으로 재현 여부를 나누고 여러 앱에서 반복되면 메모리 진단을 검토"],"warnings":["2004는 곧바로 RAM 불량을 뜻하지 않습니다. 이벤트가 지목한 프로세스와 커밋 크기를 먼저 확인하세요.","메모리 부족 상태에서 무거운 작업을 계속하면 저장하지 않은 데이터가 손실될 수 있으므로 작업을 먼저 저장하세요."],"relatedCodes":[],"relatedGuides":["windows-disk-usage-100.html","memory-test-guide.html"],"detailPage":"event-resource-exhaustion-2004.html"},{"id":"6005","source":"EventLog","level":"information","urgency":"info","summary":"Windows 이벤트 로그 서비스가 시작되었음을 기록하는 정보성 이벤트입니다. 보통 시스템 부팅 시각을 잡는 기준점으로 사용하며, 오류 자체가 아닙니다.","conditions":["Windows 부팅 직후","이벤트 로그 서비스가 다시 시작된 뒤","재부팅 전후 시간대를 비교할 때"],"causes":["정상적인 Windows 시작","이벤트 로그 서비스 재시작","업데이트·복구 작업 뒤 서비스 초기화"],"checks":["6005 시각을 Kernel-Power 41·EventLog 6008·User32 1074와 비교","부팅 시각과 실제 전원 켜기 시각이 다른지 확인","짧은 시간에 반복되면 이벤트 로그 서비스 재시작 원인과 7000 계열을 함께 확인"],"warnings":["6005는 정상 부팅·서비스 시작 기록인 경우가 대부분입니다. 이 이벤트만으로 재부팅 원인을 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-gaming-reboot.html"],"detailPage":"event-eventlog-6005.html"},{"id":"6006","source":"EventLog","level":"information","urgency":"info","summary":"Windows 이벤트 로그 서비스가 정상적인 종료 절차에서 중지되었음을 기록하는 정보성 이벤트입니다. 6006이 있고 6008이 없다면 정상 종료에 가까운 패턴으로 볼 수 있습니다.","conditions":["시작 메뉴에서 정상 종료·재시작한 뒤","Windows Update가 재부팅을 완료한 뒤","정상 종료와 강제 종료를 시간순으로 비교할 때"],"causes":["사용자가 실행한 정상 종료·재시작","Windows Update·설치 프로그램의 계획된 재부팅","관리자가 이벤트 로그 서비스를 재시작한 경우"],"checks":["6006 시각과 User32 1074의 종료 요청 시각 비교","같은 부팅 주기에 6005가 다시 기록됐는지 확인","6006 없이 6008·Kernel-Power 41만 있다면 전원 차단·강제 종료 가능성을 먼저 확인"],"warnings":["6006 자체는 오류가 아닙니다. 정상 종료 기록이 없는 것이 문제인지, 실제로 강제 종료 증상이 있었는지를 구분하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-gaming-reboot.html"],"detailPage":"event-eventlog-6006.html"},{"id":"5007","source":"Microsoft-Windows-Windows Defender","sourceAliases":["Windows Defender","Microsoft Defender Antivirus"],"level":"information","urgency":"info","summary":"Microsoft Defender Antivirus 설정이 변경되었음을 기록합니다. Defender 업데이트나 정상적인 보호 기능 전환에서도 발생하지만, 예상하지 못한 실시간 보호·예외 설정 변경이면 보안 점검이 필요합니다.","conditions":["Defender 업데이트 직후","실시간 보호·제어된 폴더 액세스 설정 변경 뒤","보안 프로그램 설치·제거 직후"],"causes":["Defender 플랫폼·보안 인텔리전스 업데이트","관리자 또는 조직 정책의 설정 변경","타사 백신 설치로 인한 보호 기능 전환","원치 않는 프로그램이 보안 설정을 변경한 경우"],"checks":["Old value와 New value에서 실제 변경된 설정 확인","Windows 보안의 바이러스 및 위협 방지 설정과 일치하는지 비교","예상하지 못한 변경이면 전체 검사와 오프라인 검사를 고려","같은 시각 5001·5004·1002 및 최근 설치·정책 변경을 함께 확인"],"warnings":["5007 단독 발생만으로 악성코드를 의미하지 않습니다. 변경 내용과 사용자의 작업·업데이트 시각이 일치하는지 확인하세요.","보호 기능을 끄거나 Defender 이벤트를 지우는 방식으로 해결하지 마세요."],"relatedCodes":[],"relatedGuides":["windows-app-not-launching.html"],"detailPage":"event-viewer-guide.html"},{"id":"1116","source":"Microsoft-Windows-Windows Defender","sourceAliases":["Windows Defender","Microsoft Defender Antivirus","WinDefend"],"level":"warning","urgency":"repeat-check","summary":"Microsoft Defender Antivirus가 악성코드 또는 유해 가능 프로그램을 탐지했음을 기록합니다. 탐지 자체이며, 실제로 제거·격리됐는지는 뒤따르는 1117 이벤트를 함께 봐야 확인됩니다.","conditions":["실시간 검사·예약 검사 중 탐지 팝업","다운로드 직후 파일이 사라짐","1117 없이 1116만 반복 기록"],"causes":["실제 악성코드·트로이목마·유해 가능 프로그램(PUA) 다운로드 또는 실행","게임 치트·크랙·키젠 같은 도구가 오탐 없이 실제로 탐지된 경우","그룹 정책·조직 설정으로 위협 기본 동작이 '작업 없음'으로 설정되어 있는 경우"],"checks":["이벤트 설명의 위협 이름(Threat Name)과 심각도, 파일 경로 기록","같은 시각 또는 직후의 1117 이벤트에서 실행된 작업(Action)이 격리·제거·허용 중 무엇인지 확인","Windows 보안의 '보호 기록'에서 같은 항목이 있는지 대조","1117 없이 1116만 반복되면 ThreatSeverityDefaultAction 등 정책 설정이 '허용'으로 바뀌어 있지 않은지 확인"],"warnings":["1116만 있고 1117(제거·격리 성공)이 없다면 위협이 실행된 채로 남아 있을 수 있습니다. 즉시 전체 검사를 실행하세요.","게임 치트·매크로 도구를 예외로 등록하기 전에 실제로 신뢰할 수 있는 출처인지 먼저 확인하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-defender-1116.html"},{"id":"1117","source":"Microsoft-Windows-Windows Defender","sourceAliases":["Windows Defender","Microsoft Defender Antivirus","WinDefend"],"level":"information","urgency":"repeat-check","summary":"Microsoft Defender Antivirus가 앞서 탐지된 위협에 대해 격리·제거·허용 중 하나의 조치를 실행했음을 기록합니다. 1116(탐지)과 짝을 이루며, 조치 결과가 '허용'이면 위협이 시스템에 남아 있다는 뜻입니다.","conditions":["1116 탐지 직후","격리함에서 파일을 확인해야 할 때","치료 후에도 증상이 남아 재확인이 필요할 때"],"causes":["Defender가 위협을 격리 또는 제거해 정상적으로 조치를 완료한 경우","정책·사용자 설정으로 조치가 '허용'으로 기록되어 위협이 그대로 실행을 허용된 경우","치료 과정에서 재부팅이 필요한 파일이라 다음 재시작 후 완료되는 경우"],"checks":["이벤트 설명의 Action(작업)이 격리·제거·허용·정리 중 무엇인지 확인","Action이 '허용'이면 예외 목록과 정책 설정을 즉시 재검토","Windows 보안의 '보호 기록'과 격리함에서 처리 결과 재확인","완전 제거가 안 됐다면 오프라인 검사(Microsoft Defender Offline)로 재검사"],"warnings":["Action이 '허용'으로 기록된 항목을 신뢰할 수 없는 출처라면 예외에서 곧바로 제거하세요.","치료 후에도 이상 동작이 계속되면 1117 하나만으로 완전히 해결됐다고 단정하지 말고 전체 검사를 다시 실행하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-defender-1117.html"},{"id":"4104","source":"Microsoft-Windows-PowerShell","sourceAliases":["PowerShell","Microsoft-Windows-PowerShell/Operational"],"level":"warning","urgency":"repeat-check","summary":"PowerShell이 컴파일해 실행한 스크립트 블록의 전체 내용을 기록합니다. 정상적인 관리 스크립트·자동화 도구도 남기지만, Base64 인코딩이나 문자열 결합으로 숨겨진 코드가 실행되면 보안 검토가 필요한 핵심 단서가 됩니다.","conditions":["보안 프로그램이 PowerShell 관련 경고를 띄운 뒤","알 수 없는 예약 작업·시작 프로그램에 PowerShell 명령이 포함된 경우","Invoke-Expression, DownloadString, FromBase64String 같은 문구가 로그에 보일 때"],"causes":["관리자·백업·업데이트 스크립트 등 정상적인 자동화 작업","설치 프로그램이나 드라이버 유틸리티가 내부적으로 사용하는 PowerShell 모듈","악성코드나 원격 침입 도구가 탐지를 피하려고 인코딩된 명령을 실행하는 경우"],"checks":["ScriptBlockId로 여러 이벤트에 나뉜 스크립트를 모아 전체 내용 재구성","Base64·문자열 결합으로 난독화된 부분이 있으면 디코딩해 실제 동작 확인","실행 계정과 부모 프로세스(예약 작업, 서비스, 문서 매크로 등) 확인","같은 시각 Windows Defender 1116·1117, 프로세스 생성 이벤트(4688)와 대조"],"warnings":["4104가 기록됐다는 사실만으로 악성 행위를 단정하지 마세요. 대부분의 관리 스크립트도 이 이벤트를 남깁니다.","낯선 다운로드·인코딩된 명령이 확인되면 네트워크 연결을 차단하고 전체 검사를 먼저 실행하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-powershell-4104.html"},{"id":"10","source":"WinMgmt","sourceAliases":["Microsoft-Windows-WMI","WMI","WinMgmt"],"level":"error","urgency":"info","summary":"WMI(Windows Management Instrumentation) 영구 이벤트 구독이 바인딩된 필터를 통해 이벤트를 전달하지 못했음을 기록합니다. 대부분 손상되거나 남아 있는 WMI 등록 정보가 원인이며, 시스템 자체의 고장을 뜻하지는 않습니다.","conditions":["시스템 로그에 반복적으로 누적","특정 소프트웨어 설치·제거 이후 시작","다른 뚜렷한 증상 없이 이벤트 개수만 늘어남"],"causes":["오래되거나 잘못 설치된 소프트웨어가 남긴 WMI 이벤트 구독·필터","OEM 유틸리티나 모니터링 프로그램의 손상된 WMI 등록","WMI 리포지토리 자체의 손상"],"checks":["이벤트 설명에서 문제가 된 필터(Filter)와 오류 코드(예: 0x80041003) 확인","wbemtest 또는 Get-WmiObject로 관련 __EventFilter, __FilterToConsumerBinding 조회","최근 설치·제거한 프로그램과 이벤트 시작 시점 비교","다른 기능 이상이 없다면 우선순위를 낮게 두고 지켜봐도 무방"],"warnings":["이 이벤트만으로 시스템이 손상됐다고 판단하지 마세요. 대개 기능상 문제를 일으키지 않는 잔여 등록 정보입니다.","리포지토리 초기화(net stop winmgmt, repository 폴더 이름 변경)는 관련 모니터링 도구가 재설정된다는 뜻이므로 신중히 진행하세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-winmgmt-10.html"},{"id":"134","source":"Time-Service","sourceAliases":["Microsoft-Windows-Time-Service","W32Time"],"level":"warning","urgency":"info","summary":"Windows Time 서비스(W32Time)가 설정된 시간 서버에 DNS로 연결하지 못해 시간 동기화에 실패했음을 기록합니다. 대개 네트워크·DNS 문제이며, 시스템 시계 자체의 고장은 아닙니다.","conditions":["절전·최대 절전에서 복귀한 직후","부팅 직후 네트워크가 아직 연결되지 않은 시점","사내망·VPN 환경에서 외부 시간 서버 접근이 막힌 경우"],"causes":["DNS 확인 실패로 time.windows.com 같은 시간 서버 이름을 찾지 못하는 경우","절전 복귀 직후 네트워크 어댑터가 아직 준비되지 않은 경우","방화벽·VPN·사내망 정책이 NTP(123번 포트) 트래픽을 차단하는 경우"],"checks":["이벤트 설명에 표시된 시간 서버 이름과 DNS 오류 코드 확인","w32tm /resync 명령으로 수동 동기화 시도","w32tm /query /status 로 현재 동기화 소스와 마지막 성공 시각 확인","사내망·VPN이라면 관리자에게 NTP(UDP 123) 아웃바운드 허용 여부 확인"],"warnings":["단발성 발생은 대개 절전 복귀나 부팅 타이밍 문제로 무해합니다.","시간이 크게 어긋나면 인증서·로그인·업데이트 오류로 이어질 수 있으니 반복되면 방치하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-time-service-134.html"},{"id":"372","source":"PrintService","sourceAliases":["Microsoft-Windows-PrintService","Print Spooler"],"level":"error","urgency":"driver","summary":"인쇄 작업이 프린터에서 실패했음을 기록합니다. 함께 표시되는 Win32 오류 코드(예: 1722 RPC 서버 사용 불가, 87 매개 변수 오류)로 원인 범위를 좁힐 수 있습니다.","conditions":["인쇄 시작 직후 실패","네트워크 프린터·프린트 서버 연결 시","특정 문서·드라이버에서만 반복"],"causes":["인쇄 스풀러 서비스 또는 스풀 파일 손상","네트워크 프린터의 RPC·공유 연결 실패(오류 코드 1722)","프린터 드라이버 손상 또는 호환성 문제","잘못된 인쇄 데이터로 스풀러가 처리 실패(오류 코드 87·259)"],"checks":["이벤트에 포함된 Win32 오류 코드 확인 후 의미 대조","인쇄 스풀러 서비스 재시작(services.msc에서 Print Spooler)","스풀 폴더(C:\\Windows\\System32\\spool\\PRINTERS)의 남은 작업 파일 삭제","프린터 드라이버 업데이트 또는 재설치, 양방향 지원 옵션 확인"],"warnings":["스풀러 재시작으로 대부분 즉시 회복되지만 반복되면 드라이버나 네트워크 연결을 먼저 점검하세요.","스풀 파일을 삭제하기 전에는 인쇄 중인 다른 작업이 없는지 확인하세요."],"relatedCodes":[],"relatedGuides":["windows-printer-offline.html","error-code-print-spooler-not-responding.html"],"detailPage":"event-print-spooler-372.html"},{"id":"10100","source":"Microsoft-Windows-DriverFrameworks-UserMode","sourceAliases":["DriverFrameworks-UserMode","WUDFHost"],"level":"information","urgency":"info","summary":"사용자 모드 드라이버 프레임워크가 장치 드라이버를 시작하거나 상태를 갱신하는 과정에서 남기는 정보 기록입니다. 장치 기능 장애가 함께 있을 때 XML의 장치 이름과 상태 코드를 확인합니다.","conditions":["부팅·절전 복귀·장치 연결 직후","USB·오디오·HID 장치 상태가 바뀐 시점","실제 장치 끊김과 같은 시간에 반복"],"causes":["정상적인 UMDF 장치 초기화","장치 드라이버 재시작","절전 복귀 중 장치 재열거"],"checks":["XML에서 DeviceName·InstanceId·Status·DriverName 확인","장치 관리자에 노란색 오류가 있는지 비교","10110·10111 또는 실제 장치 끊김이 같은 시간에 있는지 확인"],"warnings":["정보 수준의 10100만으로 USB 컨트롤러나 메인보드 고장을 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-usb-not-detected.html"],"detailPage":"event-viewer-guide.html"},{"id":"10002","source":"Microsoft-Windows-DriverFrameworks-UserMode","sourceAliases":["DriverFrameworks-UserMode","WUDFHost"],"level":"information","urgency":"info","summary":"사용자 모드 장치 드라이버의 프레임워크 통신·초기화 상태를 남기는 정보 기록입니다. 특정 장치의 재연결이나 기능 중단이 동반될 때만 원인 후보로 사용합니다.","conditions":["USB·블루투스·오디오 장치 연결 또는 절전 복귀","주변기기 재연결과 같은 시간","기능 장애 없이 단독 발생"],"causes":["정상적인 드라이버 프레임워크 상태 변경","장치 펌웨어·드라이버 재초기화","허브·절전 전원 관리 전환"],"checks":["일반 탭과 XML의 장치 이름·상태·오류 코드를 기록","같은 시간의 10110·10111과 장치 관리자 상태 비교","다른 포트·케이블·허브 없이 교차 테스트"],"warnings":["단발성 정보 기록은 하드웨어 불량 증거가 아닙니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-usb-not-detected.html"],"detailPage":"event-viewer-guide.html"},{"id":"10000","source":"Microsoft-Windows-DriverFrameworks-UserMode","sourceAliases":["DriverFrameworks-UserMode","WUDFHost"],"level":"information","urgency":"info","summary":"UMDF 드라이버 호스트와 장치가 연결되는 과정의 상태 기록입니다. 실제 장치 오류가 없다면 정상적인 부팅·연결 로그로 볼 수 있습니다.","conditions":["Windows 시작 또는 장치 연결 직후","드라이버 업데이트 뒤","주변기기 기능 저하와 동시에 반복"],"causes":["정상적인 UMDF 초기화","드라이버 업데이트·재시작","장치 전원 관리 전환"],"checks":["XML에서 장치 InstanceId와 DriverName 확인","동일 장치의 10110·10111 또는 Kernel-PnP 오류 대조","기능 장애가 없으면 조치하지 않고 반복 여부만 관찰"],"warnings":["10000 자체는 오류 이벤트가 아니며, 장치 이름 없이 하드웨어 고장을 확정할 수 없습니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"33","source":"volsnap","sourceAliases":["Volsnap","Microsoft-Windows-Volsnap"],"level":"information","urgency":"info","summary":"볼륨 섀도 복사본과 VSS 저장 영역 상태를 기록하는 정보 이벤트입니다. 백업·복원 지점이 실패하지 않는다면 단독 발생만으로 저장장치 고장을 의미하지 않습니다.","conditions":["백업·복원 지점 생성 또는 정리 뒤","VSS 작업 직후","36·25 등 volsnap 오류와 같은 시간"],"causes":["정상적인 섀도 복사본 생성·정리","백업 프로그램의 저장 영역 관리","VSS 작업 상태 변경"],"checks":["이벤트에 표시된 볼륨과 VSS 작업 결과 확인","36·Disk·Ntfs 이벤트가 같은 시각에 있는지 비교","vssadmin list shadowstorage로 저장 영역만 확인"],"warnings":["33은 정보 이벤트입니다. 백업 실패가 없다면 복원 지점을 임의로 삭제하지 마세요."],"relatedCodes":["36"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"37","source":"Microsoft-Windows-Time-Service","sourceAliases":["Time-Service","W32Time"],"level":"information","urgency":"info","summary":"Windows 시간 서비스가 동기화·상태 갱신을 수행한 기록입니다. 시계가 실제로 틀리거나 인증서·로그인 오류가 있을 때만 네트워크와 시간 서버를 점검합니다.","conditions":["부팅·절전 복귀 뒤","네트워크 연결이 바뀐 뒤","시간 동기화 상태를 확인할 때"],"causes":["정상적인 시간 서비스 상태 갱신","NTP 동기화 시도","시간 서버·네트워크 변경"],"checks":["w32tm /query /status로 마지막 동기화 상태 확인","1014·네트워크 오류와 같은 시각인지 비교","시간 오차가 없으면 정보 기록으로 분류"],"warnings":["37만으로 메인보드 배터리나 RTC 고장을 판단하지 마세요. 실제 시계 오차를 먼저 확인하세요."],"relatedCodes":["134","1014"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"7001","source":"Microsoft-Windows-Winlogon","sourceAliases":["Winlogon"],"level":"information","urgency":"info","summary":"Winlogon 세션의 로그온·로그오프 상태를 기록하는 정보 이벤트입니다. 로그인 지연이나 사용자 프로필 문제가 있을 때 관련 서비스와 같은 시각으로 해석합니다.","conditions":["로그온·로그오프·잠금 해제","부팅 후 사용자 세션 시작","로그인 지연 또는 프로필 오류와 동시 발생"],"causes":["정상적인 사용자 세션 상태 변경","그룹 정책·로그온 스크립트 처리","프로필·서비스 응답 지연"],"checks":["이벤트의 사용자·세션·상태를 기록","7000 계열·User Profile Service·로그온 지연과 비교","실제 로그인 장애가 없으면 조치하지 않음"],"warnings":["Service Control Manager의 7001과 의미가 다릅니다. 원본을 확인하지 않고 서비스 오류로 해석하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"7002","source":"Microsoft-Windows-Winlogon","sourceAliases":["Winlogon"],"level":"information","urgency":"info","summary":"Winlogon 사용자 세션이 종료되거나 상태를 전환한 기록입니다. 정상적인 로그오프·잠금에서도 발생할 수 있으며, 세션이 비정상적으로 끊길 때만 주변 이벤트를 확인합니다.","conditions":["로그오프·잠금·재부팅","원격 세션 종료","예상하지 못한 로그오프와 동시 발생"],"causes":["정상적인 세션 종료","정책·업데이트·재부팅","프로필·인증·세션 서비스 문제"],"checks":["사용자·세션 ID와 발생 시각 기록","6006·1074·User Profile Service 및 원격 세션 이벤트와 비교","실제 데이터 손실이나 반복 로그오프가 있는지 확인"],"warnings":["정보 수준의 7002만으로 계정 침해나 하드웨어 문제를 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"1038","source":"Microsoft-Windows-TPM-WMI","sourceAliases":["TPM-WMI","TPM"],"level":"information","urgency":"info","summary":"TPM WMI 관리 구성 요소가 보안 칩 상태를 조회·갱신한 기록입니다. BitLocker·Windows Hello·보안 부팅 문제가 동반될 때만 TPM 상태를 세부 확인합니다.","conditions":["부팅·로그인·BitLocker 상태 확인","BIOS·TPM 설정 변경 뒤","TPM 경고 이벤트와 같은 시간"],"causes":["정상적인 TPM 상태 조회","Windows 보안 기능 초기화","BIOS·펌웨어 변경 후 재프로비저닝"],"checks":["tpm.msc와 Get-Tpm으로 준비 상태 확인","30·TPM 오류와 발생 시각 비교","BitLocker 복구 키를 확보한 뒤에만 초기화 검토"],"warnings":["1038만으로 TPM 고장을 확정하지 마세요. 정보 이벤트이고 실제 보안 기능 상태가 더 중요합니다."],"relatedCodes":["30"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"1041","source":"Microsoft-Windows-TPM-WMI","sourceAliases":["TPM-WMI","TPM"],"level":"information","urgency":"info","summary":"TPM WMI가 보안 칩 관리 작업의 결과를 기록한 정보 이벤트입니다. 오류 상태·명령·대상 기능은 XML에서 확인해야 하며 단독 발생은 긴급하지 않습니다.","conditions":["TPM 상태 조회 또는 Windows Hello 사용","BitLocker 정책 확인","30·TPM 경고와 동시 발생"],"causes":["정상적인 TPM 관리 작업","보안 기능 초기화·정책 적용","펌웨어·BIOS 변경 후 상태 재확인"],"checks":["XML의 Result·Status·Operation 확인","Windows 보안·tpm.msc의 실제 상태 대조","기능 장애가 없으면 반복 여부만 관찰"],"warnings":["TPM 초기화는 복구 키 확인 전 실행하지 마세요."],"relatedCodes":["30"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"107","source":"Microsoft-Windows-Kernel-Power","sourceAliases":["Kernel-Power"],"level":"information","urgency":"info","summary":"Windows 전원 상태 전환·절전·재개 과정을 기록하는 정보 이벤트입니다. 비정상 종료를 판단할 때는 41·6008과 사용자 작업 시각을 함께 봅니다.","conditions":["절전·최대 절전·재개","전원 상태가 바뀐 직후","41·6008과 같은 부팅 주기"],"causes":["정상적인 전원 상태 전환","사용자 또는 정책에 따른 절전","업데이트·전원 관리 작업"],"checks":["Power-Troubleshooter·Kernel-Power 41·EventLog 6008과 시간순 비교","실제 강제 종료·재부팅이 있었는지 확인","정보 이벤트만 반복되면 전원 부품을 교체하지 않음"],"warnings":["107은 전원 공급 장치 고장을 뜻하지 않습니다. 비정상 종료 증거와 함께 해석해야 합니다."],"relatedCodes":["41","6008"],"relatedGuides":["event-viewer-guide.html","hardware-gaming-reboot.html"],"detailPage":"event-viewer-guide.html"},{"id":"187","source":"Microsoft-Windows-Kernel-Power","sourceAliases":["Kernel-Power"],"level":"information","urgency":"info","summary":"Windows가 전원 관리·절전 정책과 관련된 상태를 기록한 정보 이벤트입니다. 하드웨어 고장보다는 전원 상태 전환의 맥락을 보여주는 보조 단서입니다.","conditions":["절전·최대 절전 진입 또는 복귀","전원 계획 변경","화면 꺼짐·재개 문제와 동시 발생"],"causes":["정상적인 전원 정책 처리","장치의 절전 상태 전환","BIOS·칩셋·전원 관리 드라이버의 상태 갱신"],"checks":["같은 시간의 41·107·6008·Power-Troubleshooter 대조","화면 꺼짐이 실제 전원 손실인지 디스플레이 절전인지 구분","칩셋·그래픽 드라이버와 전원 계획 확인"],"warnings":["187 단독으로 PSU나 메인보드 불량을 확정하지 마세요."],"relatedCodes":["41","107"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"566","source":"Microsoft-Windows-Kernel-Power","sourceAliases":["Kernel-Power"],"level":"information","urgency":"info","summary":"Windows 전원 관리자 내부의 전원 상태 변경을 기록하는 정보 이벤트입니다. 발생 시각을 절전·재개·종료 기록과 맞추는 데 사용합니다.","conditions":["부팅·종료·절전 복귀","전원 버튼·덮개·정책 변경","화면 꺼짐이나 재부팅 전후"],"causes":["정상적인 전원 관리자 동작","전원 계획·장치 상태 변화","업데이트·펌웨어 적용 후 상태 갱신"],"checks":["41·6008·1074와 시간순으로 비교","사용자 조작 또는 Windows Update 재부팅과 일치하는지 확인","기능 장애가 없으면 정보 기록으로 보관"],"warnings":["566만으로 전원 공급 장치 고장을 판단하지 마세요."],"relatedCodes":["41","6008"],"relatedGuides":["event-viewer-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"19","source":"Microsoft-Windows-WindowsUpdateClient","sourceAliases":["WindowsUpdateClient","Microsoft-Windows-WindowsUpdateClient/Operational"],"level":"information","urgency":"info","summary":"Windows Update가 업데이트 검색·확인·처리 과정의 상태를 기록한 정보 이벤트입니다. 설치 실패 여부는 오류 코드와 20·25·31 등 후속 이벤트를 함께 확인해야 합니다.","conditions":["업데이트 검색·다운로드·설치 직후","재부팅 전후","업데이트 실패 메시지와 동시 발생"],"causes":["정상적인 업데이트 검색 또는 설치","정책에 따른 업데이트 확인","업데이트 서비스·네트워크 상태 변화"],"checks":["이벤트의 UpdateTitle·KB·ResultCode 확인","Windows Update 기록과 20·25·31·43·44 비교","오류 코드가 없고 설치가 완료되면 조치하지 않음"],"warnings":["WHEA-Logger의 19와 의미가 다릅니다. 원본이 WindowsUpdateClient인지 먼저 확인하세요."],"relatedCodes":["0x80072F8F"],"relatedGuides":["windows-update-fail-loop.html"],"detailPage":"event-viewer-guide.html"},{"id":"43","source":"Microsoft-Windows-WindowsUpdateClient","sourceAliases":["WindowsUpdateClient","Microsoft-Windows-WindowsUpdateClient/Operational"],"level":"information","urgency":"info","summary":"Windows Update 작업의 다운로드·설치 상태를 기록하는 정보 이벤트입니다. 실제 실패는 설명의 결과 코드와 Windows Update 오류 메시지를 기준으로 판단합니다.","conditions":["업데이트 다운로드·설치 진행","재부팅을 요구하는 업데이트","업데이트 기록에 실패가 표시될 때"],"causes":["정상적인 업데이트 처리","업데이트 재시도·재개","업데이트 구성 요소의 상태 갱신"],"checks":["KB 번호·결과 코드·재부팅 필요 여부 기록","설정의 Windows Update 기록과 대조","실패 코드가 있을 때만 네트워크·서비스·저장 공간을 점검"],"warnings":["43 정보 이벤트만으로 Windows Update 고장을 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["windows-update-fail-loop.html"],"detailPage":"event-viewer-guide.html"},{"id":"44","source":"Microsoft-Windows-WindowsUpdateClient","sourceAliases":["WindowsUpdateClient","Microsoft-Windows-WindowsUpdateClient/Operational"],"level":"information","urgency":"info","summary":"Windows Update가 업데이트 설치 또는 재부팅 후 상태를 갱신한 기록입니다. 설치 결과와 KB 번호가 실제 문제를 판단하는 핵심 정보입니다.","conditions":["업데이트 설치 완료·정리 뒤","재부팅 후","업데이트가 되돌아간 것처럼 보일 때"],"causes":["정상적인 업데이트 상태 갱신","설치 결과 기록","업데이트 재시작 작업"],"checks":["이벤트의 UpdateTitle·KB·ResultCode 확인","업데이트 기록에서 성공·실패·롤백 여부 대조","실패가 반복될 때만 DISM·Windows Update 구성 요소 점검"],"warnings":["44 자체는 오류가 아닙니다. 결과 코드 없는 정보 기록을 실패로 해석하지 마세요."],"relatedCodes":[],"relatedGuides":["windows-update-fail-loop.html"],"detailPage":"event-viewer-guide.html"},{"id":"7021","source":"Netwtw08","sourceAliases":["Netwtw08x","Intel Wireless","Intel Wi-Fi"],"level":"information","urgency":"info","summary":"Intel 무선 네트워크 드라이버가 어댑터 상태를 갱신한 정보 기록입니다. Wi-Fi 끊김·재연결이 동반될 때 드라이버와 전원 관리를 점검합니다.","conditions":["Wi-Fi 연결·절전 복귀","무선 어댑터 초기화","27·7025·7026과 같은 시간"],"causes":["정상적인 무선 드라이버 초기화","절전 전원 관리 전환","무선 드라이버·펌웨어 상태 갱신"],"checks":["XML에서 어댑터·상태·오류 코드 확인","실제 Wi-Fi 끊김과 발생 시각 비교","제조사 무선 드라이버·전원 관리 설정을 확인"],"warnings":["정보 수준 7021만으로 무선 카드 불량을 확정하지 마세요."],"relatedCodes":["27","7025","7026"],"relatedGuides":["hardware-wifi-disconnect.html"],"detailPage":"event-viewer-guide.html"},{"id":"7025","source":"Netwtw08","sourceAliases":["Netwtw08x","Intel Wireless","Intel Wi-Fi"],"level":"information","urgency":"info","summary":"Intel 무선 드라이버가 어댑터 구성 또는 상태 전환을 기록한 정보 이벤트입니다. 실제 연결 손실 여부를 함께 확인해야 합니다.","conditions":["부팅·절전 복귀","Wi-Fi 재연결","드라이버 업데이트 뒤"],"causes":["정상적인 무선 어댑터 시작·종료","전원 관리 또는 프로필 변경","드라이버 재초기화"],"checks":["어댑터 이름·상태·오류 코드를 XML에서 확인","27·1014와 연결 끊김 시각 비교","다른 무선 네트워크와 최신 제조사 드라이버로 교차 확인"],"warnings":["단발성 정보 이벤트는 무선 하드웨어 고장 증거가 아닙니다."],"relatedCodes":["27","1014"],"relatedGuides":["hardware-wifi-disconnect.html"],"detailPage":"event-viewer-guide.html"},{"id":"7026","source":"Netwtw08","sourceAliases":["Netwtw08x","Intel Wireless","Intel Wi-Fi"],"level":"information","urgency":"info","summary":"Intel 무선 드라이버가 장치·서비스 초기화 상태를 기록한 정보 이벤트입니다. 부팅 후 Wi-Fi가 실제로 늦게 올라오거나 끊길 때만 원인을 좁힙니다.","conditions":["부팅 직후","무선 드라이버 재시작","Wi-Fi 지연·끊김과 동시에 반복"],"causes":["정상적인 드라이버 초기화","칩셋·무선 드라이버 호환성","절전·빠른 시작 상태 복귀"],"checks":["장치 관리자 드라이버 버전과 이벤트 XML 대조","빠른 시작·절전 후 재현 여부 비교","다른 드라이버 버전과 동일 환경에서 테스트"],"warnings":["7026만 보고 무선 카드를 교체하지 마세요. 실제 연결 장애와 반복 조건이 필요합니다."],"relatedCodes":["27","7021"],"relatedGuides":["hardware-wifi-disconnect.html"],"detailPage":"event-viewer-guide.html"},{"id":"32","source":"e1rexpress","sourceAliases":["Intel Ethernet","Intel(R) Ethernet Connection"],"level":"information","urgency":"info","summary":"Intel 유선 네트워크 어댑터 드라이버가 링크·장치 상태를 기록한 정보 이벤트입니다. 실제 랜 연결이 끊길 때만 케이블·포트·드라이버를 함께 확인합니다.","conditions":["부팅·절전 복귀","랜 케이블 연결·해제","27·4199·1014와 같은 시간"],"causes":["정상적인 Ethernet 드라이버 초기화","링크 협상·전원 관리 전환","케이블·스위치 포트 상태 변경"],"checks":["XML의 어댑터·링크 상태 기록","실제 연결 끊김과 발생 시각 대조","다른 케이블·스위치 포트·최신 제조사 드라이버로 교차 확인"],"warnings":["e2fexpress 32와 원본이 다릅니다. 정보 수준 e1rexpress 32만으로 랜카드 고장을 판단하지 마세요."],"relatedCodes":["27","4199"],"relatedGuides":["network-connection-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"27","source":"e1rexpress","sourceAliases":["Intel Ethernet","Intel(R) Ethernet Connection"],"level":"warning","urgency":"repeat-check","summary":"Intel 유선 네트워크 어댑터가 링크를 잃었거나 네트워크 연결 상태를 경고한 기록입니다. 케이블·스위치 포트·드라이버를 순서대로 분리해 확인합니다.","conditions":["인터넷이 잠시 끊겼다가 복구","게임·파일 전송 중 랜 연결 끊김","케이블을 움직일 때 재현"],"causes":["랜 케이블·벽면 단자·스위치 포트 접촉 문제","Ethernet 드라이버·전원 관리·속도 협상 문제","공유기·스위치 또는 상대 장비 링크 불안정"],"checks":["일반 탭과 XML의 링크 상태·어댑터 이름 기록","다른 케이블·포트·네트워크에서 교차 확인","어댑터 전원 관리와 속도·듀플렉스 설정을 기본값으로 확인","4199·4266·1014와 시간대가 겹치는지 비교"],"warnings":["e2fexpress 27과 원본이 다릅니다. 오류 시각과 실제 끊김을 함께 확인한 뒤 어댑터 교체를 판단하세요."],"relatedCodes":["32","4199","4266"],"relatedGuides":["network-connection-guide.html"],"detailPage":"event-viewer-guide.html"},{"id":"18","source":"BTHUSB","sourceAliases":["Microsoft-Windows-BTHUSB","Bluetooth USB"],"level":"information","urgency":"info","summary":"Bluetooth USB 호스트 컨트롤러와 장치의 상태가 갱신된 정보 이벤트입니다. 블루투스 장치가 실제로 끊기거나 페어링에 실패할 때만 드라이버·USB 전원을 점검합니다.","conditions":["Bluetooth 장치 연결·해제","절전 복귀","헤드셋·키보드·마우스 끊김과 같은 시간"],"causes":["정상적인 Bluetooth 장치 초기화","USB 전원 관리·절전 복귀","Bluetooth 드라이버·펌웨어 재시작"],"checks":["XML에서 장치 주소·상태·오류 코드를 확인","다른 USB 포트·장치와 교차 테스트","Bluetooth·칩셋 드라이버와 USB 전원 관리 설정 확인"],"warnings":["18 정보 이벤트만으로 Bluetooth 컨트롤러 고장을 단정하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-usb-not-detected.html"],"detailPage":"event-viewer-guide.html"},{"id":"1001","source":"BugCheck","copyKey":"bugcheck-1001","sourceAliases":["Microsoft-Windows-WER-SystemErrorReporting"],"level":"error","urgency":"backup","summary":"블루스크린(정지 코드) 발생 직후 Windows가 커널 크래시 세부 정보를 시스템 로그에 남기는 기록입니다. 정지 코드와 4개의 매개변수, 덤프 파일 경로가 함께 기록되어 원인 분석의 1차 자료가 됩니다.","conditions":["블루스크린 발생 직후 재부팅 시","예기치 않은 시스템 종료 후"],"causes":["드라이버·하드웨어 오류로 인한 커널 크래시","메모리·전원 불안정으로 인한 시스템 정지","오버클럭·XMP/EXPO 설정 불안정"],"checks":["일반 탭 본문에서 정지 코드(예: 0x0000009c)와 매개변수 4개를 확인","같은 시각의 WHEA-Logger·Kernel-Power 이벤트를 함께 대조","C:\\Windows\\Minidump 폴더의 덤프 파일을 이 사이트의 미니덤프 분석기로 분석","이 이벤트가 여러 번 쌓여 있다면 정지 코드가 매번 같은지 비교 — 반복될 때마다 코드가 다르게 나온다면 특정 드라이버보다 메모리(RAM) 불량을 먼저 의심"],"warnings":["이 기록 자체는 원인이 아니라 크래시가 발생했다는 사실과 상세 정보를 남길 뿐입니다. 정지 코드로 원인 후보를 좁히세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","minidump-analyzer.html","memory-test-guide.html"],"detailPage":"event-bugcheck-1001.html"},{"id":"109","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"커널 전원 관리자가 종료(또는 재시작) 전환을 시작했음을 기록합니다. 시작 메뉴·전원 버튼·프로그램의 종료 요청 같은 정상적인 종료에서도 남는 정보성 기록입니다.","conditions":["Windows를 종료하거나 재시작할 때","Windows Update 뒤 자동 재시작","전원 버튼으로 종료할 때"],"causes":["정상 종료·재시작 요청","Action·Reason 값이 가리키는 요청 주체(커널, 사용자, 프로그램)"],"checks":["Action(종료 방식)과 Reason 값을 확인","같은 시각 뒤에 Kernel-Power 41(비정상 종료)이 이어졌는지 확인","User32 1074(종료 요청 주체)와 시각 비교"],"warnings":["정보성 기록이라 단독으로는 문제가 아닙니다. 이 이벤트 뒤에 41이나 6008이 없다면 정상 종료로 보는 것이 맞습니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html","hardware-gaming-reboot.html"]},{"id":"130","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"절전(S3) 모드로 들어갈 때 펌웨어가 걸린 시간(SuspendStart·SuspendEnd)을 남기는 정보성 기록입니다.","conditions":["절전 모드로 들어갈 때마다","노트북 덮개를 닫거나 절전을 실행할 때"],"causes":["정상적인 절전 진입 기록"],"checks":["절전 진입이 유독 오래 걸린다면 SuspendStart와 SuspendEnd 값의 차이를 다른 날과 비교","절전 뒤 화면이 안 켜지는 증상이 함께 있으면 131(복귀 시간)과 함께 확인"],"warnings":["정보성 기록이며 오류가 아닙니다. 값 자체만으로 부품 고장을 판단하지 마세요."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"]},{"id":"131","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"절전(S3)에서 깨어날 때 펌웨어가 복귀하는 데 걸린 시간(ResumeCount·FullResume·AverageResume)을 남기는 정보성 기록입니다.","conditions":["절전 모드에서 복귀할 때마다"],"causes":["정상적인 절전 복귀 기록"],"checks":["복귀가 느리다는 체감이 있으면 FullResume 값을 다른 날과 비교","복귀 뒤 화면·네트워크가 돌아오지 않는 증상이 있으면 그래픽·네트워크 드라이버와 172를 함께 확인"],"warnings":["정보성 기록이며 오류가 아닙니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"]},{"id":"172","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"대기(절전) 상태에서 네트워크 연결이 유지되는지(Connectivity state in standby)와 그 이유를 기록합니다. 'NIC compliance'는 네트워크 어댑터가 대기 중 연결 유지 조건을 충족하지 않는다고 판단해 연결을 끊는 경우에 나옵니다.","conditions":["절전·대기 모드로 들어갈 때","현대적 대기(Modern Standby)를 지원하는 PC"],"causes":["정상적인 대기 중 네트워크 연결 정책(Disconnected/Connected)","네트워크 어댑터·드라이버가 대기 중 연결 유지 조건을 지원하지 않음"],"checks":["절전 복귀 뒤 네트워크가 끊긴 채로 돌아오는 증상이 있을 때만 확인","네트워크 어댑터 전원 관리('전원을 절약하기 위해 컴퓨터가...')와 드라이버 버전 확인"],"warnings":["Disconnected 자체는 오류가 아닙니다. 증상이 없다면 조치할 필요가 없습니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"]},{"id":"577","source":"Kernel-Power","sourceAliases":["Microsoft-Windows-Kernel-Power"],"level":"information","urgency":"info","summary":"시스템이 스스로 시작하는 재부팅(예: 업데이트·드라이버 설치 뒤 재시작)을 준비했다는 정보성 기록입니다.","conditions":["Windows Update·드라이버 설치 뒤 시스템이 재시작을 시작할 때"],"causes":["시스템이 요청한 정상 재시작"],"checks":["같은 시각의 Windows Update·설치 이벤트와 User32 1074를 비교","재시작 뒤 Kernel-Power 41이 없다면 정상 재시작"],"warnings":["정보성 기록이며 단독으로는 문제가 아닙니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"]},{"id":"55","source":"Kernel-Processor-Power","sourceAliases":["Microsoft-Windows-Kernel-Processor-Power"],"level":"information","urgency":"info","summary":"부팅 때 논리 프로세서마다 CPU가 알려 주는 전원 관리 기능(유휴 상태, 성능 상태, 기준 주파수, 최대·최소 성능 비율)을 기록하는 정보성 이벤트입니다.","conditions":["부팅할 때마다 논리 프로세서 수만큼 한꺼번에 기록됨"],"causes":["정상 부팅 기록 — 건수는 논리 프로세서 수 × 부팅 횟수"],"checks":["건수가 (논리 프로세서 수 × 부팅 횟수)와 크게 다르지 않은지 확인","유휴 상태 수나 성능 상태 방식이 표시되지 않으면 BIOS의 CPU 전원 관리(C-state, CPPC) 설정을 확인","성능 저하·과열 문제는 이 이벤트가 아니라 같은 공급자의 다른 ID(예: 37)와 온도 기록으로 확인"],"warnings":["오류나 경고가 아닙니다. 건수가 많아 보여도 정상입니다."],"relatedCodes":[],"relatedGuides":["event-viewer-guide.html"]}]});
